/* DAWAH X — ahmad, অধ্যায় 121 · খণ্ড 121 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][121]=[[24001,24001,"","তিনি বললেন, আমি করুণার পর্দার উপর পড়েছি: আপনার বাবার জীবনের জন্য আপনার টাকা তার বাবার জন্য একটি গুরুতর অপরাধ, তার জীবন কেড়ে নেওয়ার স্বপ্ন দেখেছি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى فِي جِدَارِ الْقِبْلَةِ بُصَاقًا ‏ ‏أَوْ مُخَاطًا أَوْ ‏ ‏نُخَامَةً ‏ ‏فَحَكَّهُ ‏","","",""],[24002,24002,"","আমরা আপনার জন্য সবচেয়ে ভাল একটি ছেলে গ্রহণ করা হয়েছে যে একজন যাজকের কাছ থেকে ক্ষমার দ্বারা বিভক্ত হয়েছে. ঋণ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏رَخَّصَ أَنْ يُسْتَمْتَعَ بِجُلُودِ الْمَيْتَةِ إِذَا دُبِغَتْ ‏","","",""],[24003,24003,"","আমরা আপনার জন্য সবচেয়ে ভাল কথা বলেছি ... ... ঈশ্বরের প্রতি বাবার ভালবাসা হারানোর জন্য আপনি ... ... ...তার উপর আদেশ দিয়েছেন তাকে... সে বলেছে আমি তোমাকে অনুসরণ করতে চাই এবং তাকে বলতে চাই সে গাছ পেয়েছে, তাই আমি ঈশ্বর এবং আল্লাহ শান্তি এবং তার শক্তি আছে, আমি আপনাকে বলছি তুমি ঈশ্বরে বিশ্বাস করো আর তাকে বলো যে সে আমার কথা শুনবে না। তুমি কি বলো, ঈশ্বর এবং তার বার্তাবাহকের উপর বিশ্বাস রাখো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نِيارٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏بَدْرٍ ‏ ‏فَتَبِعَهُ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْمُشْرِكِينَ فَلَحِقَهُ عِنْدَ ‏ ‏الْجَمْرَةِ ‏ ‏فَقَالَ إِنِّي أَرَدْتُ أَنْ أَتْبَعَكَ وَأُصِيبَ مَعَكَ قَالَ تُؤْمِنُ بِاللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ قَالَ لَا قَالَ ارْجِعْ فَلَنْ نَسْتَعِينَ بِمُشْرِكٍ قَالَ ثُمَّ لَحِقَهُ عِنْدَ الشَّجَرَةِ فَفَرِحَ بِذَاكَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ لَهُ قُوَّةٌ وَجَلَدٌ فَقَالَ جِئْتُ لِأَتْبَعَكَ وَأُصِيبَ مَعَكَ قَالَ تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ قَالَ لَا قَالَ ‏ ‏ارْجِعْ فَلَنْ أَسْتَعِينَ بِمُشْرِكٍ قَالَ ثُمَّ لَحِقَهُ حِينَ ظَهَرَ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏فَقَالَ لَهُ مِثْلَ ذَلِكَ قَالَ تُؤْمِنُ بِاللَّهِ وَرَسُولِهِ قَالَ نَعَمْ قَالَ فَخَرَجَ بِهِ ‏","","",""],[24004,24004,"","আমরা ঈশ্বরের অনুগ্রহ নিয়ে কথা বলেছি, আমি বরং তোমার লর্ডশিপের সাথে বাস করতে চাই। ঈশ্বরের শান্তি আছে, এটা চার বার, একটি গবাদি পশু, এবং স্ত্রী ছাড়া যাবে না। সাত বছর আগে সে আর ফোন করতো না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏بِكَمْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ قَالَتْ ‏ ‏بِأَرْبَعٍ وَثَلَاثٍ وَسِتٍّ وَثَلَاثٍ وَثَمَانٍ وَثَلَاثٍ وَعَشْرَةٍ وَثَلَاثٍ وَلَمْ يَكُنْ ‏ ‏يُوتِرُ ‏ ‏بِأَكْثَرَ مِنْ ثَلَاثَ عَشْرَةَ وَلَا أَنْقَصَ مِنْ سَبْعٍ وَكَانَ لَا يَدَعُ رَكْعَتَيْنِ ‏","","",""],[24005,24005,"","আমরা ঈশ্বরের প্রেম নিয়ে কথা বলেছিলাম... ...আমি চাই আমি যেন তার বাবা, ঈশ্বর জঙ্গলে উদ্ধার করুক, অথবা তাকে জিজ্ঞেস করি সে তোমার সব অনুসন্ধানে ঘুম পাড়িয়ে দিয়েছে. সম্ভবত তাকে ছেড়ে দেওয়া হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَيْفَ كَانَ نَوْمُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجَنَابَةِ أَيَغْتَسِلُ قَبْلَ أَنْ يَنَامَ فَقَالَتْ كُلَّ ذَلِكَ قَدْ كَانَ يَفْعَلُ ‏ ‏رُبَّمَا اغْتَسَلَ فَنَامَ وَرُبَّمَا تَوَضَّأَ فَنَامَ قَالَ قُلْتُ لَهَا كَيْفَ كَانَتْ قِرَاءَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ أَيَجْهَرُ أَمْ يُسِرُّ قَالَتْ كُلَّ ذَلِكَ قَدْ كَانَ يَفْعَلُ رُبَّمَا جَهَرَ وَرُبَّمَا أَسَرَّ ‏","","",""],[24006,24006,"","আমার বাবা হয়তো শুনেছিলেন যে, ঈশ্বর তার পিতা ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَحَفَّظُ مِنْ هِلَالِ شَعْبَانَ مَا لَا يَتَحَفَّظُ مِنْ غَيْرِهِ ثُمَّ يَصُومُ بِرُؤْيَةِ رَمَضَانَ فَإِنْ غُمَّ عَلَيْهِ عَدَّ ثَلَاثِينَ يَوْمًا ثُمَّ صَامَ ‏","","",""],[24007,24007,"","আমরা ঈশ্বর সম্বন্ধে আমাদের আলোচনাকে সবচেয়ে ভাল করে বলেছি। তিনি আমার সাথে একটি বিখ্যাত কথোপকথনের মাধ্যমে আমার সাথে লিখে দিয়েছেন। আমি বললাম, আমি কথা বলি না। তোমার কাছে এটা শুনে, ঈশ্বর এটা করেছেন আর আমি সব বলবো। আমি হয়ত বলবো যদি আমার একজন লোক তার সাথে কথা বলে, আমি বলতাম, যদি আমাদের মধ্যে থাকে। বাবা কথা বলেছে, বাবা ভেঙ্গেছে আর বলেছে যদি আমাদের কথা বলে, সে একজন মানুষ তার কিছু একটা হারালো, আর সে কখনো সেটা করেনি তার আগে। তুমি যদি এই কথোপকথনের ব্যাপারে কথা বলতে, তাহলে ঈশ্বর হয়তো এটা ভুলে যেতে পারেন যদিও আমি ভেবেছিলাম আমাকে ফোন করা হয়েছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ يَعْنِي ابْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏أَنَّ ‏ ‏النُّعْمَانَ بْنَ بَشِيرٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏كَتَبَ مَعِي ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَ فَقَدِمْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَدَفَعْتُ إِلَيْهَا كِتَابَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَتْ يَا بُنَيَّ أَلَا أُحَدِّثُكَ بِشَيْءٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَتْ فَإِنِّي كُنْتُ أَنَا ‏ ‏وَحَفْصَةُ ‏ ‏يَوْمًا مِنْ ذَاكَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ كَانَ عِنْدَنَا رَجُلٌ يُحَدِّثُنَا فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَا أَبْعَثُ لَكَ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَسَكَتَ ثُمَّ قَالَ لَوْ كَانَ عِنْدَنَا رَجُلٌ يُحَدِّثُنَا فَقَالَتْ ‏ ‏حَفْصَةُ ‏ ‏أَلَا أُرْسِلُ لَكَ إِلَى ‏ ‏عُمَرَ ‏ ‏فَسَكَتَ ثُمَّ قَالَ لَا ثُمَّ دَعَا رَجُلًا فَسَارَّهُ بِشَيْءٍ فَمَا كَانَ إِلَّا أَنْ أَقْبَلَ ‏ ‏عُثْمَانُ ‏ ‏فَأَقْبَلَ عَلَيْهِ بِوَجْهِهِ وَحَدِيثِهِ فَسَمِعْتُهُ يَقُولُ لَهُ يَا ‏ ‏عُثْمَانُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَعَلَّهُ أَنْ يُقَمِّصَكَ قَمِيصًا فَإِنْ أَرَادُوكَ عَلَى خَلْعِهِ فَلَا تَخْلَعْهُ ثَلَاثَ مِرَارٍ ‏ ‏قَالَ ‏ ‏فَقُلْتُ يَا ‏ ‏أُمَّ الْمُؤْمِنِينَ ‏ ‏فَأَيْنَ كُنْتِ عَنْ هَذَا الْحَدِيثِ فَقَالَتْ ‏ ‏يَا بُنَيَّ وَاللَّهِ لَقَدْ أُنْسِيتُهُ حَتَّى مَا ظَنَنْتُ أَنِّي سَمِعْتُهُ ‏","","",""],[24008,24008,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং পঞ্চমবারের জন্য প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[24009,24009,"","আমরা যুদ্ধের মাধ্যমে দুই সেলমোন তৈরি করেছি, যে বিয়েতে জয় করেছে, সে বলবে, সে নাকি ঈশ্বরের অনুগ্রহ এবং আনন্দ কামনা করে আমার বাবা ঈশ্বরের দেবতা দ্বারা পরাজিত হবে.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي رُكُوعِهِ ‏ ‏سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏ ‏قَالَ وَقَالَ ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏فِي رُكُوعِهِ وَسُجُودِهِ ‏","","",""],[24010,24010,"","আমরা একটি ছেলের প্রথার প্রতি আসক্তির কথা বলেছি, যিনি এক বছর ধরে চলে গেছেন। লর্ড প্রার্থনা করলেন এবং বললেন, সকালে তার রক্ত নিয়ে ভয় পাওয়া উচিত সব রক্ত, বলতে চাই, কেন আমি ঘুমাতে যেতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَرَكْعَتَيْ الْفَجْرِ لَهُمَا خَيْرٌ مِنْ الدُّنْيَا جَمِيعًا ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَسْتَمِعُ هَذَا الْحَدِيثَ فَيَقُولُ ‏ ‏لَهُمَا أَحَبُّ إِلَيَّ مِنْ حُمْرِ النَّعَمِ ‏","","",""],[24011,24011,"","আমরা আবেগ নিয়ে কথা বলেছি, আমরা এক তরুণীর সাথে দেখা করতে পেরে খুশি হয়েছি, আমি ঈশ্বরের কাছে প্রার্থনা করব যেন আমি তার জন্য প্রার্থনা করি এবং আমি পর্দা থেকে কেটে ফেলতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِالْأَجْرَاسِ أَنْ تُقْطَعَ مِنْ أَعْنَاقِ الْإِبِلِ يَوْمَ ‏ ‏بَدْرٍ ‏","","",""],[24012,24012,"","আমরা কথা বলেছিলাম কিভাবে একে অপরের সাথে কথা বলতে হয়, তুমি বলতে চাও গ্রীষ্মের কথা, কি সুন্দর আর আমাকে বলতে চাও যে একটা টোপ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُقْبَلُ صَلَاةُ حَائِضٍ إِلَّا بِخِمَارٍ ‏","","",""],[24013,24013,"","আমরা আমার বাবার সঙ্গে কথা বলেছিলাম । তার বাসায় রাখা এবং গর্ভপাতে অ্যাপার্টমেন্টে রাখা আমার কাছে বলা হয়েছে, যখন আমি এমন কিছু করতে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي حَسَّانَ ‏ ‏أَنَّ رَجُلًا قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏إِنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏الطِّيَرَةَ ‏ ‏فِي الْمَرْأَةِ وَالدَّارِ وَالدَّابَّةِ فَغَضِبَتْ غَضَبًا شَدِيدًا فَطَارَتْ شُقَّةٌ مِنْهَا فِي السَّمَاءِ وَشُقَّةٌ فِي الْأَرْضِ فَقَالَتْ إِنَّمَا ‏ ‏كَانَ أَهْلُ الْجَاهِلِيَّةِ ‏ ‏يَتَطَيَّرُونَ ‏ ‏مِنْ ذَلِكَ ‏","","",""],[24014,24014,"","আমরা শেষবারের কথা বলেছি, ঈশ্বরের দোহাই, তারপর সে আমার আগে বের হয়ে যাবে এবং আমি যা করব তার আগে হবে। সে আসবে এবং সে তাকে আঘাত করার জন্য তার ঘৃণা করবে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ لِآلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحْشٌ إِذَا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَدَّ وَلَعِبَ وَأَقْبَلَ وَأَدْبَرَ فَإِذَا أَحَسَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ دَخَلَ ‏ ‏رَبَضَ ‏ ‏فَلَمْ ‏ ‏يَتَرَمْرَمْ ‏ ‏كَرَاهِيَةَ أَنْ يُؤْذِيَهُ ‏","","",""],[24015,24015,"","বাবার পুরো বই নিয়ে আমরা কথা বলেছিলাম তার মত জীবন যাপনের জন্য. বন্ধুত্ব, আমাদের একটা উপহার আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي عُتْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ تُصُدِّقَ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏مِنْ لَحْمِ ‏ ‏الصَّدَقَةِ ‏ ‏فَذُهِبَ بِهِ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقِيلَ إِنَّهُ مِنْ لَحْمِ ‏ ‏الصَّدَقَةِ ‏ ‏قَالَ ‏ ‏إِنَّمَا هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[24016,24016,"","আমরা তোমাকে অতীতের কাজ সম্পর্কে বলেছিলাম । জীবন মানেই সে হল থামিয়েছে। আমি যা ভেবেছিলাম তা উপভোগ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ ‏ ‏خَدِيجَةَ ‏ ‏فَقُلْتُ لَقَدْ ‏ ‏أَعْقَبَكَ ‏ ‏اللَّهُ عَزَّ وَجَلَّ مِنْ امْرَأَةٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مِنْ عَجُوزَةٍ مِنْ عَجَائِزِ ‏ ‏قُرَيْشٍ ‏ ‏مِنْ نِسَاءِ ‏ ‏قُرَيْشٍ ‏ ‏حَمْرَاءِ ‏ ‏الشِّدْقَيْنِ ‏ ‏هَلَكَتْ فِي الدَّهْرِ قَالَتْ ‏ ‏فَتَمَعَّرَ ‏ ‏وَجْهُهُ ‏ ‏تَمَعُّرًا ‏ ‏مَا كُنْتُ أَرَاهُ إِلَّا عِنْدَ نُزُولِ الْوَحْيِ أَوْ عِنْدَ ‏ ‏الْمَخِيلَةِ ‏ ‏حَتَّى يَنْظُرَ أَرَحْمَةٌ أَمْ عَذَابٌ ‏","","",""],[24017,24017,"","কিন্তু সে ঈশ্বরকে বলেছিল যে, সে যে - জীবন পেয়েছে, তা সম্বন্ধে তাকে বলেছিল । তারপর বেরিয়ে এসে বললো, যদি সে এটা হত্যা করে তাহলে সে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَمُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيجٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْمُغِيرَةُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ بِنْتِ أَبِي بَكْرٍ ‏ ‏أَنَّهَا أَخْبَرَتْهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ حَتَّى ذَهَبَ عَامَّةُ اللَّيْلِ وَحَتَّى نَامَ أَهْلُ الْمَسْجِدِ ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏رَقَدَ ‏ ‏ثُمَّ خَرَجَ فَصَلَّى فَقَالَ ‏ ‏إِنَّهُ لَوَقْتُهَا لَوْلَا أَنْ يَشُقَّ عَلَى أُمَّتِي ‏ ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏أَنْ أَشُقَّ ‏","","",""],[24018,24018,"","আমরা সবচেয়ে ভালো কথা বলেছি যে ছেলে এসেছে সে বলবে যে তাকে ঘুম থেকে নিয়ে আসতে এবং তোমার পতাকা পড়তে হবে আর সে তাকে মেরে ফেলবে দেখতে পাচ্ছি না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏هَذَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يَقْرَأُ عَلَيْكِ السَّلَامَ فَقَالَتْ وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ ‏ ‏تَرَى مَا لَا نَرَى ‏","","",""],[24019,24019,"","আমি আমার জীবনে যে সমস্ত জীবন কাটিয়েছি তার মধ্যে সবচেয়ে ভালো কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন এবং আমি তার সাথে কথা বলতে ব্যর্থ হব না। তিনি আপনাকে আমার বাবার সাথে ফাকা দিয়ে যেতে বলছেন। সে ভবিষ্যদ্বাণীর মাধ্যমেই আছে, ঈশ্বর তার কাজ করেছেন। তার মন বলে যে তোমার মেয়েরা আমাকে হারিয়ে ফেলতে বলেছে এবং তোমাকে একটা নোংরা নাটকে খুঁজে বের করতে বলেছে, ঈশ্বর তাকে ভালবাসবেন, আমি তাকে ভালোবাসি। আমি জানি, আমি জানি, ঈশ্বর তোমাকে ভালোবাসি। আমি তাকে মারতে যাচ্ছি না। আমি ওকে ওর কাছে ফিরে যেতে বলবো না। আমি এমন একটা জেনাকে শিখাব যেটা একটা জীবন্ত দানব যে আমার সাথে ঘুমাচ্ছিল। সে বলল, তুমি আমার কাছে ফিরে যাও। বাবার এই ভুলের কথা বলছে যে সে একটা বোকা-মানুষ হবে, আমি তার জন্য ভাববাদী প্রার্থনা করছি আর আমি তাকে মরতে দেখতে আত্মসমর্পণ করব। আমি ভেবেছিলাম তাকে হারাতে আমার ঘৃণা হবে না। আমি এটা করবো। আমি এটা করতে চাই। আমি জানি, আমি যদি আমার বাবা আমার কাছে ফিরে যাই, আমি তাকে হারাতে চাই। আমি যদি আমার কাছে এটা একটা ছোট জিনিস চাই, তাহলে আমি তাকে ছেড়ে দেব। আর আমি যদি আমি এটা করবো, আমি জানি যে আমি এটা করবো, আমি জানি, আমি জানি না যে আমি এটা একটা ছোট ছেলে-মেয়ে। আমি যদি তার জন্য একটা জিনিস চাই, তাহলে আমি এটা করবো। আমি জানি যে আমি তাকে আমি এটা করবো। আমি যদি আমার কাছে একটা ছোট হব, আমি এটা করতে চাই, তাহলে আমি এটা একটা জিনিস। আমি চাই। আমি জানি যে আমি জানি না। আমি জানি যে তুমি জানো না যে তুমি এটা একটা জিনিস। তাকে আমার বাবাকে তার বাবাকে বড় হতে দাও আর আমি আর অন্য কোন নারীকে দেখতে চাই না। যে কোন কিছু ঘটে গেলে, ঈশ্বর কোন মানুষের জন্য লজ্জা বোধ করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اجْتَمَعْنَ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَرْسَلْنَ ‏ ‏فَاطِمَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْنَ لَهَا قُولِي لَهُ إِنَّ نِسَاءَكَ ‏ ‏يَنْشُدْنَكَ ‏ ‏الْعَدْلَ فِي ‏ ‏ابْنَةِ أَبِي قُحَافَةَ ‏ ‏قَالَتْ فَدَخَلَتْ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مَعَ ‏ ‏عَائِشَةَ ‏ ‏فِي ‏ ‏مِرْطِهَا ‏ ‏فَقَالَتْ لَهُ إِنَّ نِسَاءَكَ أَرْسَلْنَنِي إِلَيْكَ وَهُنَّ ‏ ‏يَنْشُدْنَكَ ‏ ‏الْعَدْلَ فِي ‏ ‏ابْنَةِ أَبِي قُحَافَةَ ‏ ‏فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُحِبِّينِي قَالَتْ نَعَمْ قَالَ ‏ ‏فَأَحِبِّيهَا فَرَجَعَتْ إِلَيْهِنَّ فَأَخْبَرَتْهُنَّ مَا قَالَ لَهَا فَقُلْنَ إِنَّكِ لَمْ تَصْنَعِي شَيْئًا فَارْجِعِي إِلَيْهِ فَقَالَتْ وَاللَّهِ لَا أَرْجِعُ إِلَيْهِ فِيهَا أَبَدًا ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَكَانَتْ ابْنَةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَقًّا ‏ ‏فَأَرْسَلْنَ ‏ ‏زَيْنَبَ بِنْتَ جَحْشٍ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏هِيَ الَّتِي كَانَتْ ‏ ‏تُسَامِينِي ‏ ‏مِنْ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ إِنَّ أَزْوَاجَكَ أَرْسَلْنَنِي إِلَيْكَ وَهُنَّ ‏ ‏يَنْشُدْنَكَ ‏ ‏الْعَدْلَ فِي ‏ ‏ابْنَةِ أَبِي قُحَافَةَ ‏ ‏قَالَتْ ثُمَّ أَقْبَلَتْ عَلَيَّ تَشْتُمُنِي فَجَعَلْتُ أُرَاقِبُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنْظُرُ إِلَى ‏ ‏طَرْفِهِ ‏ ‏هَلْ يَأْذَنُ لِي فِي أَنْ أَنْتَصِرَ مِنْهَا فَلَمْ يَتَكَلَّمْ قَالَتْ فَشَتَمَتْنِي حَتَّى ظَنَنْتُ أَنَّهُ لَا يَكْرَهُ أَنْ أَنْتَصِرَ مِنْهَا فَاسْتَقْبَلْتُهَا فَلَمْ أَلْبَثْ أَنْ أَفْحَمْتُهَا قَالَتْ فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏ابْنَةُ أَبِي بَكْرٍ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَلَمْ أَرَ امْرَأَةً خَيْرًا مِنْهَا وَأَكْثَرَ صَدَقَةً وَأَوْصَلَ لِلرَّحِمِ ‏ ‏وَأَبْذَلَ لِنَفْسِهَا فِي كُلِّ شَيْءٍ يُتَقَرَّبُ بِهِ إِلَى اللَّهِ عَزَّ وَجَلَّ مِنْ ‏ ‏زَيْنَبَ ‏ ‏مَا عَدَا سَوْرَةً مِنْ ‏ ‏غَرْبٍ ‏ ‏حَدٍّ كَانَ فِيهَا تُوشِكُ مِنْهَا ‏ ‏الْفِيئَةَ ‏","","",""],[24020,24020,"","আমরা বিয়ের ব্যাপারে কথা বলেছি, আর তার ঈর্ষার কথা বলছি, আমি একজন লেখক, যিনি তাকে উদ্ধার করেছেন আর তাকে দিয়েছেন। দ্যা ওয়ালথ বলেছেন, \"দ্যা ওয়ালথ\" সে তার মাথার উপর হাত রেখে বলল আমি ঈশ্বরের প্রতি এতটাই ভালবাসা রাখি যে, আমি তার কথা পড়ি না, নারী, এবং ঈশ্বর কখনো আমাদের জন্য কিছু বলেননি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَوْ غَيْرِهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ بِنْتُ عُتْبَةَ بْنِ رَبِيعَةَ ‏ ‏تُبَايِعُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخَذَ عَلَيْهَا ‏ { ‏أَنْ لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا وَلَا يَسْرِقْنَ وَلَا يَزْنِينَ ‏} ‏الْآيَةَ ‏ ‏قَالَتْ فَوَضَعَتْ يَدَهَا عَلَى رَأْسِهَا حَيَاءً فَأَعْجَبَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا رَأَى مِنْهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَقِرِّي أَيَّتُهَا الْمَرْأَةُ فَوَاللَّهِ مَا بَايَعَنَا إِلَّا عَلَى هَذَا قَالَتْ فَنَعَمْ إِذًا فَبَايَعَهَا بِالْآيَةِ ‏","","",""],[24021,24021,"","আমরা এক বছরের কথা বলেছি, যার নাম একটি দয়ার জন্য তার একটা নাম খুঁজে পাওয়া। সে বলল, সে ঈশ্বরকে ঈশ্বরের দোহাই দিয়ে প্রার্থনা করতে দেখেছে এবং সে তার মুখ উজ্জ্বল করে। আর সে তার মুখ উজ্জ্বল করে। আর আমি জানি, আমি আমার জীবনের সব কিছু একটা, আমার মনে নেই। আমি মনে করি, আমি মনে করি, আমি আমার ছেলের নাম জানি, আমি আমার বাবা, আমি আমার বাবা, আমি আমার বাবা, আমি তাকে বলেছিলাম, আমি আমার ছেলের নাম খুঁজে পেয়েছি। আমি আমার বাবা, আমি তাকে বলেছিলাম, আমি আমার বাবা, আমি আমার কাছে এটা একটা ছোট্ট ছেলের সাথে কথা বলেছি। আর আমি তাকে বলেছিলাম, আমি আমার ছেলের নাম দিয়েছি। আমি আমার মনে করতে চাই না যে, আমি তাকে বলেছিলাম, আমি আমার ছেলের কথা বলছি, আমি আমার ছেলের সাথে আমার মনের কথা বলছি। আমি আমার ছেলের কথা বলছি, আমি তাকে আমি আমার মনের কথা বলতে চাই। আমি আমার বাবা-মা'র কথা বলছি, আমি তাকে বলেছিলাম, আমি আমার মনের সামনে তোমার সামনে তোমার সামনে তুলে ধরতে পারি। আর আমি যখন আমি তাকে বলেছিলাম, আমি আমার মনের কথা বলি, আমি আমার মনের কথা বলি, আমি তাকে বলি, আমি আমার ছেলের সামনে তুলে ধরতে পারি। পানি আর সে ঈশ্বরের কাছে বলে আমি বলতে চাচ্ছি আমাকে মরতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏مُوسَىِ بْنِ سَرْجِسٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَمُوتُ وَعِنْدَهُ قَدَحٌ فِيهِ مَاءٌ يُدْخِلُ يَدَهُ فِي الْقَدَحِ وَيَمْسَحُ وَجْهَهُ بِالْمَاءِ وَهُوَ يَقُولُ ‏ ‏اللَّهُمَّ أَعِنِّي عَلَى سَكَرَاتِ الْمَوْتِ ‏","","",""],[24022,24022,"","আমরা আমাদের সুখী ছেলের জীবন সম্বন্ধে কথা বলেছিলাম, যিনি বলেছিলেন যে তিনি একটা ছেলে মারা যেতে পারেন । ( পড়ুন, গীতসংহিতা ৩৭: ১১.)","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَامِرَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْفُ بْنُ الْحَارِثِ بْنِ الطُّفَيْلِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ يَا ‏ ‏عَائِشَةُ ‏ ‏إِيَّاكِ ‏ ‏وَمُحَقِّرَاتِ ‏ ‏الذُّنُوبِ فَإِنَّ لَهَا مِنْ اللَّهِ عَزَّ وَجَلَّ طَالِبًا ‏","","",""],[24023,24023,"","বাবার আশীর্বাদে আমরা কথা বলেছি যে আমি বাবাকে বলেছি আমার মেয়ে আছে, ঈশ্বরের কাছে একটা রাতের জন্য আত্মসমর্পণ করতে হবে। আমি ভেবেছিলাম সে তার দুর্দশার কিছু কষ্ট ভোগ করেছে। তুমি যদি না বলো... ...আমার বাবা বলবে তুমি আমাকে মেরে ফেলবে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتِ ‏ ‏افْتَقَدْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَظَنَنْتُ أَنَّهُ ذَهَبَ إِلَى بَعْضِ نِسَائِهِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فَتَحَسَّسْتُ ‏ ‏ثُمَّ رَجَعْتُ ‏ ‏فَإِذَا هُوَ ‏ ‏رَاكِعٌ ‏ ‏أَوْ سَاجِدٌ ‏ ‏يَقُولُ سُبْحَانَكَ وَبِحَمْدِكَ لَا إِلَهَ إِلَّا أَنْتَ فَقُلْتُ بِأَبِي أَنْتَ وَأُمِّي إِنَّكَ لَفِي شَأْنٍ وَإِنِّي لَفِي شَأْنٍ آخَرَ ‏","","",""],[24024,24024,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তারা যে - দুর্দশা ভোগ করেছেন, সেগুলোর জন্য তারা মারা গিয়েছে । আমি কথা দিচ্ছি, আমি এমন এক দুর্দশার মধ্যে বাস করছি, যা আমরা স্ক্রিপ্টের বাক্সে জমা দেব এবং বিয়ের পর বের হওয়ার পর বাইরে চলে যাব। আপনি আমাকে বলেছেন আমার ছেলের নাম তার জন্য আছে আমাকে একটি রাত জন্য আমাকে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَوْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ ‏ ‏صُبُّوا عَلَيَّ مِنْ سَبْعِ قِرَبٍ لَمْ تُحْلَلْ ‏ ‏أَوْكِيَتُهُنَّ ‏ ‏لَعَلِّي أَسْتَرِيحُ فَأَعْهَدَ إِلَى النَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَأَجْلَسْنَاهُ فِي ‏ ‏مِخْضَبٍ ‏ ‏لِحَفْصَةَ ‏ ‏مِنْ نُحَاسٍ وَسَكَبْنَا عَلَيْهِ الْمَاءَ مِنْهُنَّ حَتَّى ‏ ‏طَفِقَ ‏ ‏يُشِيرُ إِلَيْنَا أَنْ قَدْ فَعَلْتُنَّ ثُمَّ خَرَجَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏فَمَا ‏ ‏تَبْتَغِي ‏ ‏بِذَلِكَ قَالَ أَمَّا سُبْحَانَكَ وَبِحَمْدِكَ لَا إِلَهَ إِلَّا أَنْتَ فَأَخْبَرَنِي ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا افْتَقَدَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ فَظَنَّتْ ‏","","",""],[24025,24025,"","আমরা যত বেশি পার্টির কথা বলেছি, ততই আমার বাবা বলেছেন, তিনি তার সবচেয়ে ভালো আছেন। আমি আপনাদের সবাইকে ঈশ্বরের কাছে বলব, আল্লাহ আছে। ঈশ্বর আমাকে রক্ষা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ كُلُّ نِسَائِكَ لَهَا كُنْيَةٌ غَيْرِي فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اكْتَنِي أَنْتِ ‏ ‏أُمَّ عَبْدِ اللَّهِ ‏ ‏فَكَانَ يُقَالُ لَهَا ‏ ‏أُمُّ عَبْدِ اللَّهِ ‏ ‏حَتَّى مَاتَتْ وَلَمْ تَلِدْ قَطُّ ‏","","",""],[24026,24026,"","ঈশ্বরের একজন স্বপ্নের ব্যক্তি হতে পেরে তিনি একজন স্বপ্নের অধিকারী হতে পেরেছেন, যার কাছে রয়েছে । তাকে হত্যা করতে বলা হয়েছে, সে ভগবানের কাছে কিছু বলছে আর সে আর সে নির্দোষ আর নির্দোষদের উদ্ধার করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِمْتُ فَرَأَيْتُنِي فِي الْجَنَّةِ فَسَمِعْتُ صَوْتَ قَارِئٍ يَقْرَأُ فَقُلْتُ مَنْ هَذَا ‏ ‏قَالُوا هَذَا ‏ ‏حَارِثَةُ بْنُ النُّعْمَانِ ‏ ‏فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَاكَ ‏ ‏الْبِرُّ ‏ ‏كَذَاكَ ‏ ‏الْبِرُّ ‏ ‏وَكَانَ ‏ ‏أَبَرَّ ‏ ‏النَّاسِ ‏ ‏بِأُمِّهِ ‏","","",""],[24027,24027,"","আমরা আমার বাবার মেয়ে বা তার ঈর্ষার কথা বলেছিলাম... ...একজন বোকাকে ঈশ্বরের ইচ্ছার কাছে প্রার্থনা করতে বলা হয়েছিল মিথ্যা থেকে আত্মসমর্পণ করতে আর হয়ত সে মানুষ হতে পারে. মিথ্যা বলে ফেলো, যখন সে তার আত্মা চলে যায়... ...সে জানে আমি তার সাথে কথা বলতে চেষ্টা করবো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَوْ غَيْرِهِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ خُلُقٌ أَبْغَضَ إِلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْكَذِبِ وَلَقَدْ ‏ ‏كَانَ الرَّجُلُ يَكْذِبُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَذِبَةَ فَمَا يَزَالُ فِي نَفْسِهِ عَلَيْهِ حَتَّى يَعْلَمَ أَنْ قَدْ أَحْدَثَ مِنْهَا تَوْبَةً ‏","","",""],[24028,24028,"","আমরা আমাদের সর্বোত্তমটা নিয়ে আলোচনা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فَإِذَا انْصَرَفَ قَالَ لِي قُومِي فَأَوْتِرِي ‏","","",""],[24029,24029,"","আমরা ক্রেতাদের সঙ্গে নগ্ন হওয়ার বিষয়ে কথা বলেছিলাম । ওয়ার্ড, সে তার কিছু জিনিস পাবে, আর সে থাকবে একজন মহিলা, যে চলে গেছে, সে একটা ভালো কথা বলছে যে ঈশ্বরকে এটা দিতে হবে আর আমি কখনই দেখতে পারবো না যে তিনি যা জানেন না আমি যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَجُلٌ يَدْخُلُ عَلَى أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُخَنَّثٌ ‏ ‏وَكَانُوا يَعُدُّونَهُ مِنْ غَيْرِ أُولِيَ ‏ ‏الْإِرْبَةِ ‏ ‏فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا وَهُوَ عِنْدَ بَعْضِ نِسَائِهِ وَهُوَ ‏ ‏يَنْعَتُ ‏ ‏امْرَأَةً ‏ ‏فَقَالَ إِنَّهَا إِذَا أَقْبَلَتْ أَقْبَلَتْ بِأَرْبَعٍ وَإِذَا ‏ ‏أَدْبَرَتْ ‏ ‏أَدْبَرَتْ ‏ ‏بِثَمَانٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَرَى هَذَا يَعْلَمُ مَا هَا هُنَا لَا يَدْخُلْ عَلَيْكُنَّ هَذَا فَحَجَبُوهُ ‏","","",""],[24030,24030,"","আমরা ঈশ্বরের জীবনের শপথ নিয়ে কথা বলেছি, ঈশ্বর তাকে এটা কিভাবে করতে হবে, আর তাকে এটা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏بِرْذَوْنٍ ‏ ‏عَلَيْهِ عِمَامَةٌ ‏ ‏طَرْفُهَا ‏ ‏بَيْنَ كَتِفَيْهِ فَسَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُ فَقَالَ ‏ ‏رَأَيْتِيهِ ‏ ‏ذَاكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[24031,24031,"","আমরা ঈশ্বরের ছেলের জন্য তোমার পার্টনারের কথা বলেছিলাম, আমার বাবা এক দশক ধরে তার জন্য প্রার্থনা করেছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي ابْنَ بِلَالٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَتِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي عَجْوَةِ الْعَالِيَةِ شِفَاءٌ ‏ ‏أَوْ ‏ ‏تِرْيَاقٌ ‏ ‏أَوَّلَ ‏ ‏الْبُكْرَةِ ‏ ‏عَلَى ‏ ‏الرِّيقِ ‏","","",""],[24032,24032,"","সে তার মুখ দিয়ে তাকিয়েছিল যে সে আমাকে বলবে সে নাকি আমি তাকে বলতে চাই নি তিনি এটা দিয়েছেন এবং তিনি আত্মসমর্পণ করেছেন যে তিনি কারাগার থেকে সরে এসেছেন।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْكَرِيمِ ‏ ‏أَنَّ ‏ ‏مُجَاهِدًا ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏مَوْلًى ‏ ‏لِعَائِشَةَ ‏ ‏أَخْبَرَهُ ‏ ‏كَانَ يَقُودُ بِهَا أَنَّهَا كَانَتْ إِذَا سَمِعَتْ صَوْتَ الْجَرَسِ أَمَامَهَا قَالَتْ قِفْ بِي فَيَقِفُ حَتَّى لَا تَسْمَعَهُ وَإِذَا سَمِعَتْهُ وَرَآهَا قَالَتْ أَسْرِعْ بِي حَتَّى لَا أَسْمَعَهُ وَقَالَتْ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لَهُ تَابِعًا مِنْ الْجِنِّ ‏","","",""],[24033,24033,"","আমরা একটা দুর্বল মায়ের কথা বলেছিলাম, যাকে ঈশ্বরকে দিতে হতো। সে তার ঊর্ধ্বতন এবং তার অভিজাত মানুষদের জীবনের বড় বড়টাকে ছেড়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أُمِّ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُرْسَلُ عَلَى الْكَافِرِ حَيَّتَانِ وَاحِدَةٌ مِنْ قِبَلِ رَأْسِهِ وَأُخْرَى مِنْ قِبَلِ رِجْلَيْهِ تَقْرِضَانِهِ قَرْضًا كُلَّمَا فَرَغَتَا عَادَتَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[24034,24034,"","ঈশ্বরের একজন পুত্র আছে, যার বলতে হবে যে, এটাই সর্বোত্তম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يُغْتَسَلُ مِنْ أَرْبَعٍ مِنْ الْجُمُعَةِ وَالْجَنَابَةِ ‏ ‏وَالْحِجَامَةِ ‏ ‏وَغَسْلِ الْمَيِّتِ ‏","","",""],[24035,24035,"","আমরা আমার বাবার সাথে যা ঘটেছে তার কথা বলেছিলাম, আমরা তার নিজের জীবন দিয়ে তাকে কি দিতে চেয়েছিলাম, তাকে বলতে হবে যে সে একজন মহিলাকে তার টাকা আর তার ঋণের জন্য বিয়ে করছে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُزَوَّجُ الْمَرْأَةُ لِثَلَاثٍ لِمَالِهَا وَجَمَالِهَا وَدِينِهَا فَعَلَيْكَ بِذَاتِ الدِّينِ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكَ ‏","","",""],[24036,24036,"","তিনি আপনাদের মধ্যে একজনকে সেখান থেকে কতটা ধোয়ান তা মুছে ফেলুন । পানি.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيْمَنُ بْنُ نَابِلٍ ‏ ‏عَنْ ‏ ‏أُمِّ كُلْثُومٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قِيلَ لَهُ إِنَّ فُلَانًا وَجِعٌ لَا يَطْعَمُ الطَّعَامَ قَالَ ‏ ‏عَلَيْكُمْ ‏ ‏بِالتَّلْبِينَةِ ‏ ‏فَحَسُّوهُ إِيَّاهَا فَوَالَّذِي نَفْسِي بِيَدِهِ إِنَّهَا لَتَغْسِلُ بَطْنَ أَحَدِكُمْ كَمَا يَغْسِلُ أَحَدُكُمْ وَجْهَهُ بِالْمَاءِ مِنْ الْوَسَخِ ‏","","",""],[24037,24037,"","আমরা বাবার জীবন নিয়ে একটা স্বপ্ন দেখি। সে ঘোড়াটা পড়ে গেছে। ঈশ্বরকে বলে তার নাম ছিল তোমার বাবা যা বলেছে তাই হলো। আল্লাহ তাঁর সাথে এমন করেছে, আপনার স্বামীকে বলে যে আপনি চলে যেতে চান, আর বলেন যে সব শেষ হয়ে গেছে। আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ آيَةُ الْخِيَارِ دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنِّي أُرِيدُ أَنْ أَذْكُرَ لَكِ أَمْرًا فَلَا تَقْضِينَ فِيهِ شَيْئًا دُونَ أَبَوَيْكِ فَقَالَتْ مَا هُوَ قَالَتْ فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَ عَلَيَّ هَذِهِ الْآيَةَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ ‏} { ‏إِنْ كُنْتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ ‏} ‏الْآيَةَ كُلَّهَا قَالَتْ فَقُلْتُ قَدْ اخْتَرْتُ اللَّهَ وَرَسُولَهُ قَالَتْ فَفَرِحَ لِذَلِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24038,24038,"","ঈশ্বর অজাতের অন্ধকারের হাত থেকে রাজ্যগুলো উদ্ধার করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُلِقَتْ الْمَلَائِكَةُ مِنْ نُورٍ وَخُلِقَتْ الْجَانُّ مِنْ ‏ ‏مَارِجٍ ‏ ‏مِنْ نَارٍ ‏ ‏وَخُلِقَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مِمَّا وُصِفَ لَكُمْ ‏","","",""],[24039,24039,"","আমরা আমাদের জীবনের সবচেয়ে ভালো টাকা নিয়ে কথা বলেছি। হয়তো বেঁচে থাকাটা ছিল ঈশ্বরের কাছে তার সর্বোচ্চ শান্তি। যতক্ষণ না না আমরা বলবো না, আমি বলবো না, আমি জিজ্ঞেস করতে পারব না। ঈশ্বর তার শান্তির জন্য তাকে আত্মসমর্পণ করুন এবং এটা থেকে দুইভাবে মাছ হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ أَبُو النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ وَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَكْمَلَ صِيَامَ شَهْرٍ قَطُّ إِلَّا رَمَضَانَ وَمَا رَأَيْتُهُ فِي شَهْرٍ قَطُّ أَكْثَرَ مِنْهُ صِيَامًا فِي شَعْبَانَ ‏","","",""],[24040,24040,"","আমরা আপনাদের টাকাপয়সা সম্বন্ধে কথা বলেছিলাম কিন্তু ঈশ্বরের একজন যাজক ছিলেন, যিনি একজন যাজক ছিলেন । মৃত্যু","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنِ ‏ ‏ابْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ أَنْ يُسْتَمْتَعَ بِجُلُودِ الْمَيْتَةِ إِذَا دُبِغَتْ ‏","","",""],[24041,24041,"","আমি সবসময় বলব যে, আমি হয়তো লক্ষণগুলো কল্পনা করতে পারি । আমি এটা করি নি, আমি ঘুম থেকে জেগে উঠি, যা কেউ ঢুকতে পারে না এবং সেখান থেকে বের হতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَرْفَجَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَقَالَ ‏ ‏لَقَدْ صَنَعْتُ الْيَوْمَ شَيْئًا وَدِدْتُ أَنِّي لَمْ أَفْعَلْهُ دَخَلْتُ الْبَيْتَ ‏ ‏فَأَخْشَى أَنْ يَجِيءَ الرَّجُلُ مِنْ أُفُقٍ مِنْ الْآفَاقِ فَلَا يَسْتَطِيعُ دُخُولَهُ فَيَرْجِعُ وَفِي نَفْسِهِ مِنْهُ شَيْءٌ ‏","","",""],[24042,24042,"","আমরা সবার সেরাটা নিয়ে কথা বলেছি, যারা প্রার্থনা করছিল তাদের বিয়ের কথা আমাদের বলা হয়েছে। সে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَايِعُ النِّسَاءَ بِالْكَلَامِ بِهَذِهِ الْآيَةِ ‏ { ‏عَلَى أَنْ لَا يُشْرِكْنَ بِاللَّهِ شَيْئًا ‏} ‏قَالَتْ وَمَا مَسَّتْ يَدُهُ يَدَ امْرَأَةٍ قَطُّ إِلَّا امْرَأَةً يَمْلِكُهَا ‏","","",""],[24043,24043,"","আমি ভাববাদীর প্রার্থনা করছি এবং আমার বন্দীকে প্রেমের পোশাকে উদ্ধার করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُجِّيَ ‏ ‏فِي ثَوْبِ ‏ ‏حِبَرَةٍ ‏","","",""],[24044,24044,"","আমরা বাবার অন্ত্যেষ্টিক্রিয়ার হাত জয় করার চেষ্টা করেছি, তার পরিবারের সাথে বিশ্বাসঘাতকতা করার জন্য, ঈশ্বর নিষেধ করেছেন, ঈশ্বর সবার জন্য, আমি বেঁচে আছি।","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ سَلَمَةَ الْمَخْزُومِيِّ ‏ ‏عَنِ ‏ ‏الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ عَلَى كُلِّ أَحْيَانِهِ ‏","","",""],[24045,24045,"","আমরা আমার ছেলের এক লোককে কথা বলেছিলাম যে তার সাথে ডিনার করেছিল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سُوَاءَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِيمَا يَفِيضُ بَيْنَ الرَّجُلِ وَامْرَأَتِهِ مِنْ ‏ ‏الْمَاءِ ‏ ‏قَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُبُّ ‏ ‏الْمَاءَ ‏ ‏عَلَى ‏ ‏الْمَاءِ ‏","","",""],[24046,24046,"","আমরা একটি জীবনের দশম বাস থাকার কারণে বিখ্যাত হওয়ার কথা বলেছি। আমি প্রথমে ঈশ্বরের কাছে প্রার্থনা করি এবং আপনার নীরব যোদ্ধার দৃষ্টি তুলে ধরতে চাই। আমরা আর নখের মত আসতে পারছি না।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏وَيُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْوَحْيِ الرُّؤْيَا الصَّادِقَةُ ‏ ‏أَوْ قَالَ الرُّؤْيَا الصَّالِحَةُ شَكَّ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏قَالَتْ وَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ ‏","","",""],[24047,24047,"","আমি বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করছেন আর তিনি হয়তো তার ভয়কে কাটিয়ে উঠতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمُرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ قُلْتُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ صَوْتَهُ بِالْقِرَاءَةِ قَالَتْ ‏ ‏رُبَّمَا رَفَعَ وَرُبَّمَا خَفَضَ ‏","","",""],[24048,24048,"","আমরা মৃত্যুর জন্য বিখ্যাত হয়ে যাওয়া নিয়ে কথা বলেছি, ঈশ্বরের হাত তাকে এবং গবাদি পশুশালির এক নারীকে হাত দিয়ে প্রার্থনা করছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا مَسَّتْ يَدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَ امْرَأَةٍ فِي بَيْعَةٍ قَطُّ ‏","","",""],[24049,24049,"","আমরা মারা যাওয়ার কথা বলেছিলাম, বাবার কাছে গিয়ে আমার বাবাকে দেখতে চাইলে, সে ভিক্ষা চায় এবং ভিক্ষা চায় এবং গথোকে দেখতে না গিয়ে গথিয়োর কাছে প্রার্থনা করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَغْتَسِلُ وَيُصَلِّي الرَّكْعَتَيْنِ وَصَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏لَا أَرَاهُ يُحْدِثُ وُضُوءًا بَعْدَ الْغُسْلِ ‏","","",""],[24050,24050,"","ঈশ্বর প্রতিজ্ঞা করেছেন যে, তিনি প্রতিজ্ঞা করেছেন এবং নীরব আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَيْمُونٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[24051,24051,"","কালো মহিলা আমাকে বলেছিল যে আমি যে - ক্রেতাদের কাছে থাকতাম, তাদের মূল্য দেওয়া হবে । তার কথা না বলা, তোমার মা আর তোমার আত্মাকে ভয় করা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ أَنَّهُ يَقْطَعُ الصَّلَاةَ الْكَلْبُ الْأَسْوَدُ وَالْمَرْأَةُ الْحَائِضُ ‏ ‏قَالَ ‏ ‏عَطَاءٌ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى وَهِيَ مُعْتَرِضَةٌ بَيْنَ يَدَيْهِ وَقَالَ أَلَيْسَ هُنَّ ‏ ‏أُمَّهَاتِكُمْ وَأَخَوَاتِكُمْ وَعَمَّاتِكُمْ ‏","","",""],[24052,24052,"","আমরা আমার বাবা আমাদের জন্য একটি ছেলের জন্য সংরক্ষণ চেষ্টা কথা বলেছিলাম যে তিনি বলেছেন যে ভাল তিনি লর্ডের প্রার্থনা এবং তিনি যদি ঘুমের প্রয়োজন হয় তাহলে তাকে আত্মসমর্পণ করতে হবে. সে লিখেছে, \"ঈশ্বর, আমি যাচ্ছি, আমি যাই আর যাই।\" সে বলেছিল তোমার এক প্রাণে শহীদের ছেলেকে হত্যা করতে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ النَّوْمَ جَمَعَ يَدَيْهِ فَيَنْفُثُ فِيهِمَا ثُمَّ يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ‏ ‏وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ ‏ ‏ثُمَّ ‏ ‏يَمْسَحُ ‏ ‏بِهِمَا وَجْهَهُ وَرَأْسَهُ وَسَائِرَ جَسَدِهِ ‏ ‏قَالَ ‏ ‏عُقَيْلٌ ‏ ‏وَرَأَيْتُ ‏ ‏ابْنَ شِهَابٍ ‏ ‏يَفْعَلُ ذَلِكَ ‏","","",""],[24053,24053,"","ঈশ্বরের একজন বাসা তার কাছে প্রার্থনা করে এবং এরপর সবচেয়ে শক্তিশালী লোকেদের কাছে প্রার্থনা করে । ফোন করেছিল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏حَدَّثَنِي ‏ ‏جَعْفَرُ بْنُ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعِشَاءَ ثُمَّ صَلَّى ثَمَانِ رَكَعَاتٍ قَائِمًا وَرَكْعَتَيْنِ جَالِسًا بَيْنَ النِّدَاءَيْنِ لَمْ يَكُنْ يَدَعُهُمَا ‏","","",""],[24054,24054,"","আমরা আশা করেছিলাম বাবা হয়তো আমাদের সময় বাঁচিয়ে রাখতে পারবে, সে আল্লাহ্‌র কাছে প্রার্থনা করবে যখন সে এটা পরতে চায়। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমার মন হারিয়ে যায়নি । শাস্তি।","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏مُوسَىِ بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا ‏ ‏خَدِيجَةَ ‏ ‏فَأَطْنَبَ ‏ ‏فِي الثَّنَاءِ عَلَيْهَا فَأَدْرَكَنِي مَا يُدْرِكُ النِّسَاءَ مِنْ الْغَيْرَةِ فَقُلْتُ لَقَدْ أَعْقَبَكَ اللَّهُ يَا رَسُولَ اللَّهِ مِنْ عَجُوزٍ مِنْ عَجَائِزِ ‏ ‏قُرَيْشٍ ‏ ‏حَمْرَاءِ ‏ ‏الشِّدْقَيْنِ ‏ ‏قَالَتْ فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَغَيُّرًا لَمْ أَرَهُ تَغَيَّرَ عِنْدَ شَيْءٍ قَطُّ إِلَّا عِنْدَ نُزُولِ الْوَحْيِ أَوْ عِنْدَ ‏ ‏الْمَخِيلَةِ ‏ ‏حَتَّى يَعْلَمَ رَحْمَةٌ أَوْ عَذَابٌ ‏","","",""],[24055,24055,"","আমি যখন আমার ছেলের যত্ন নেওয়ার জন্য চেষ্টা করি, তখন আমি তাকে বলেছিলাম যে, তিনি মারা যাবেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَمَلَ مِنْ أُمَّتِي دَيْنًا ثُمَّ جَهَدَ فِي قَضَائِهِ ثُمَّ مَاتَ قَبْلَ أَنْ يَقْضِيَهُ فَأَنَا ‏ ‏وَلِيُّهُ ‏","","",""],[24056,24056,"","ঈশ্বরের কাছে করা ভাববাদীর প্রার্থনা তাকে বলেছিল যে, তিনি তাকে বলেছিলেন যে, তিনি যদি জিজ্ঞেস করতেন, তা হলে তিনি আমাকে সাহায্য করবেন । ভালোরা তার ছেলেকে বলেছে যে ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তিনি জানতে পেরেছেন যে তিনি তাকে বিক্রি করতে যাচ্ছেন। এটা বিশ্বাস করা একটা স্বস্তি যে ভালো কোন সহকর্মীর কখনও হবে না। ওর সাথে কথা বল, শক্ত-কুত্তার মত কিছু নেই।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمُرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّهَا سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الطَّاعُونِ فَأَخْبَرَهَا نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏عَذَابًا يَبْعَثُهُ اللَّهُ عَزَّ وَجَلَّ عَلَى مَنْ يَشَاءُ فَجَعَلَهُ اللَّهُ رَحْمَةً لِلْمُؤْمِنِينَ فَلَيْسَ مِنْ عَبْدٍ وَقَعَ الطَّاعُونُ فِي بَلَدِهِ فَيَمْكُثُ فِي بَلَدِهِ صَابِرًا مُحْتَسِبًا يَعْلَمُ أَنَّهُ لَنْ يُصِيبَهُ إِلَّا مَا كَتَبَ اللَّهُ لَهُ إِلَّا كَانَ لَهُ مِثْلُ أَجْرِ شَهِيدٍ ‏","","",""],[24057,24057,"","আমি বাবার ছেলের জন্মের ব্যাপারে কথা বলেছি, সে শুনে যাজকেরা দশ বছর বয়সের কথা শোনে। লর্ড তার কাছে প্রার্থনা করে আর তাকে রাজি হতে বলে। একটি গৌরব অথবা হত্যাকৃত অন্ত্যেষ্টিক্রিয়ায় নারীদের সম্প্রদায়।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي الْوَلِيدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يُخْبِرُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا خَيْرَ فِي جَمَاعَةِ النِّسَاءِ إِلَّا فِي مَسْجِدٍ أَوْ فِي جَنَازَةِ قَتِيلٍ ‏","","",""],[24058,24058,"","আমরা তর্কের কথা বলেছি... ...তোমার পার্টনারকে বলেছিলাম... ...আর আমরা যা বলছি তা হল... ...আমি একটা স্বপ্নের মধ্যে বাস করছি... ...তার কাছে প্রার্থনা করার জন্য... মৃত ব্যক্তি বলেছিলেন যে, তার মস্তিষ্ক রান্না করা হয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏وَحُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ جُلُودِ الْمَيْتَةِ فَقَالَ ‏ ‏دِبَاغُهَا ‏ ‏طَهُورُهَا ‏","","",""],[24059,24059,"","আমরা প্রজাপতির সঙ্গে একটা বাচ্চা নিয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْوَزَغِ ‏ ‏فُوَيْسِقٌ ‏ ‏وَلَمْ أَسْمَعْهُ أَمْرَ بِقَتْلِهِ ‏","","",""],[24060,24060,"","আমরা তর্কের কথা বলেছি একটা ভালো ছেলেকে সাহায্য করার চেষ্টা করার ব্যাপারে। ঝড় তাকে বলল যে আমি ওর জন্য প্রার্থনা করি আর তারপর আত্মসমর্পণ করি। আর সে আত্মসমর্পণ করে আর সে তার বিছানায় যেতে বাধ্য ছিল। আর তারপর সে চলে গেল, আর তারপর সে তার কুকুস খুঁজে পেল। যদি তুমি তাকে ক্ষমা করে দাও, সে আমাকে আর আমার সাথে দেখা করতে বলবে। তাহলে তোমার উত্তর তার প্রয়োজন, আমি আমার বাবাকে আলাদা করে দিয়েছি আর তুমি কিভাবে ঈশ্বরকে হত্যা করেছ, আমি ভয় পাচ্ছি এটা করার জন্য ঈশ্বর করতে হবে। আমার বাবা এমন এক সুখী ছেলের জন্য পালিয়ে যাচ্ছেন, যার জীবন ভেঙে গিয়েছে । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏يَحْيَىِ بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْعَاصِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعُثْمَانَ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏اسْتَأْذَنَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُضْطَجِعٌ عَلَى فِرَاشِهِ لَابِسٌ ‏ ‏مِرْطَ ‏ ‏عَائِشَةَ ‏ ‏فَأَذِنَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَهُوَ كَذَلِكَ فَقَضَى إِلَيْهِ حَاجَتَهُ ثُمَّ انْصَرَفَ فَاسْتَأْذَنَ ‏ ‏عُمَرُ ‏ ‏فَأَذِنَ لَهُ وَهُوَ عَلَى تِلْكَ الْحَالِ فَقَضَى إِلَيْهِ حَاجَتَهُ ثُمَّ انْصَرَفَ ثُمَّ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏ثُمَّ اسْتَأْذَنَ عَلَيْهِ فَجَلَسَ وَقَالَ ‏ ‏لِعَائِشَةَ ‏ ‏اجْمَعِي عَلَيْكِ ثِيَابَكِ فَقَضَى إِلَيْهِ حَاجَتَهُ ثُمَّ انْصَرَفَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ مَا لِي لَمْ أَرَكَ فَزِعْتَ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏كَمَا فَزِعْتَ ‏ ‏لِعُثْمَانَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ وَإِنِّي خَشِيتُ إِنْ أَذِنْتُ لَهُ عَلَى تِلْكَ الْحَالِ أَنْ لَا يَبْلُغَ إِلَيَّ فِي حَاجَتِهِ قَالَ ‏ ‏لَيْثٌ ‏ ‏وَقَالَ جَمَاعَةُ النَّاسِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏أَلَا أَسْتَحِي مِمَّنْ تَسْتَحِي مِنْهُ الْمَلَائِكَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏اسْتَأْذَنَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَابِسٌ ‏ ‏مِرْطًا ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[24061,24061,"","আমি বাবাকে মৃত্যুর জন্য আমার বাবাকে নিয়ে আসার ব্যাপারে কথা বলেছিলাম, সে নাকি অতীতের আত্মার জন্য বেঁচে থাকবে বলে সে বলেছিল, এমনকি আমি ঈশ্বরের দোহাইর কাছে প্রার্থনাও করিনি। আমি বলেছিলাম, আমি যদি আমার বাবার কাছে এটা না বলি, আমি যদি আমার বাবার কাছে কিছু না বলি, তাহলে আমি এটা খেতে চাই। আমি যদি আমার বাবার কাছে ফিরে যাই, তাহলে আমি আমার বাবার কাছে এটা একটা জিনিস আছে। আমি বলব, আমি যদি আমার বাবার কাছে এটা বিক্রি করি, আমি এটা নিয়ে কথা বলি, তাহলে আমি তোমাকে বলব। আর আমি বলব, আমি যদি আমার বাবার কাছে ফিরে যাই, তাহলে আমি এটা একটা ছোট হব। আমি জানি যে, আমি জানি, আমি কি করবো। আমি জানি যে, আমি এটা একটা গোপন কথা বলছি, আমি যদি তুমি জানো না, আমি এটা একটা কথা বলি, তাহলে আমি তোমার জন্য না যে, আমি তোমাকে বলছি, আমি এটা আমার বাবার মত করে দিলাম। আর আমি যদি তুমি জানো, আমি এটা আমার বাবার কাছে একটা প্রশ্ন করি, তাহলে আমি তোমার জন্য। আমি এটা একটা প্রশ্ন করি, আমার উত্তর হচ্ছে, তিনি যুক্তির যুক্তি থেকে সব কিছু মুছে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏الْحَارِثُ بْنُ يَعْقُوبَ الْأَنْصَارِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي يَزِيدَ الْأَنْصَارِيِّ ‏ ‏عَنِ ‏ ‏امْرَأَتِهِ ‏ ‏أَنَّهَا سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ لُحُومِ الْأَضَاحِيِّ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏عَلِيٌّ ‏ ‏مِنْ سَفَرٍ فَقَدَّمْنَا إِلَيْهِ مِنْهُ فَقَالَ لَا آكُلُهُ حَتَّى أَسْأَلَ عَنْهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ فَسَأَلَهُ ‏ ‏عَلِيٌّ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُوهُ مِنْ ذِي الْحِجَّةِ إِلَى ذِي الْحِجَّةِ ‏","","",""],[24062,24062,"","আমরা সেই যুক্তি নিয়ে কথা বলেছি যে ছেলেটির পশম দিয়ে গিয়েছিল। সে আত্মসমর্পণ করবে যে তার বাবা-মা থেকে মেয়ে পর্যন্ত মারা যাবে। আর তারপর তাকে মুখ দিয়ে যেতে হবে, একটা ফ্লায়ার বানানো হয়েছিল, তার প্রতি ভদ্র আচরণ ছিল আর সে সব কিছু শুনতেই বলেছিল সে বলবে আপনি যে রোগকে মোকাবেলা করতে চান, তার জন্য বরফ হয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا كَانَتْ إِذَا مَاتَ الْمَيِّتُ مِنْ أَهْلِهَا فَاجْتَمَعَ النِّسَاءُ ثُمَّ تَفَرَّقْنَ إِلَّا أَهْلَهَا وَخَاصَّتَهَا أَمَرَتْ بِبُرْمَةٍ مِنْ ‏ ‏تَلْبِينَةٍ ‏ ‏فَطُبِخَتْ ثُمَّ صُنِعَ ثَرِيدٌ فَصُبَّتْ ‏ ‏التَّلْبِينَةُ ‏ ‏عَلَيْهَا ثُمَّ قَالَتْ كُلْنَ مِنْهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏التَّلْبِينَةُ ‏ ‏مَجَمَّةٌ ‏ ‏لِفُؤَادِ الْمَرِيضِ تَذْهَبُ بِبَعْضِ الْحُزْنِ ‏","","",""],[24063,24063,"","আমি যখন সেখানে পৌঁছাই, তখন আমার বাবা আমার সঙ্গে কথা বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ ‏ ‏الْغَائِطِ ‏ ‏قَالَ غُفْرَانَكَ ‏","","",""],[24064,24064,"","আমি বলেছিলাম যে, ভাববাদী তার কাছে প্রার্থনা করেন এবং আমি আরও ভাল বোধ করি ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ أَحْسَنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي ‏","","",""],[24065,24065,"","আমরা একটা জীবন নিয়ে কথা বলেছি যেটা চুপ থাকার জন্য ছিল, ঈশ্বরের কাছে আছে আর আমি ফোন করছি আর আমি তাকে টাকা দিচ্ছি.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي وَأَنَا بِإِزَائِهِ ‏","","",""],[24066,24066,"","আমরা যেদিন মৃত্যুর বয়স নিয়ে কথা বলেছিলাম, আমি ঈশ্বরের কাছে প্রার্থনা করতে ভয় পাচ্ছি আর সে এটা পরিবর্তন করবে, অথবা তাদের মধ্যে দু'জন চলে যাবে, অথবা এমন ঘটনা যা কখনো ব্যর্থ হবে না। রুম থেকে বেরিয়ে যাওয়া এমন একটা জায়গায় গিয়ে পৌঁছে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ رَاشِدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ يَعْفُرَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا صَلَّى الْعِشَاءَ دَخَلَ الْمَنْزِلَ ثُمَّ صَلَّى رَكْعَتَيْنِ ثُمَّ صَلَّى بَعْدَهُمَا ‏ ‏رَكْعَتَيْنِ أَطْوَلَ مِنْهُمَا ثُمَّ أَوْتَرَ بِثَلَاثٍ لَا يَفْصِلُ فِيهِنَّ ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ يَرْكَعُ وَهُوَ جَالِسٌ وَيَسْجُدُ وَهُوَ قَاعِدٌ جَالِسٌ ‏","","",""],[24067,24067,"","আমরা বাবার জীবিত থাকার অটুট কাজগুলো সম্বন্ধে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا شَبِعَ آلُ ‏ ‏مُحَمَّدٍ ‏ ‏ثَلَاثًا مِنْ خُبْزِ ‏ ‏بُرٍّ ‏ ‏حَتَّى قُبِضَ وَمَا رُفِعَ مِنْ مَائِدَتِهِ كِسْرَةٌ قَطُّ حَتَّى قُبِضَ ‏","","",""],[24068,24068,"","আমরা আমার বাবাকে ড্রাইভ করার চেষ্টা করেছি... ...আমাদের কাছে যে ঈশ্বর আমার নিজের পুত্র আছে, তিনি বলেছিলেন যে তিনি যা কিছু করেছিলেন তার জন্য আমি মায়ের কাছে অনুরোধ করব. তিনি বলেন বড় হতে এবং বলেন, \"ঈশ্বর, Goths এবং mones, এবং আমি চলে যাব।\" আপনি যখন বিশ্বাসঘাতকতা করছেন, আপনি সাক্ষী হবেন আপনি আমার প্রতি বিশ্বাসঘাতকতা করছেন তখন আপনার উপাসনার মধ্যে সাক্ষ্য। আমি কেন এটা নিয়ে গেলাম, একজন রক্ষণশীল পুলিশ বলল যে আমার বাবা তার জন্য প্রার্থনা করত এবং তার শান্তির জন্য আমি আপনাকে হত্যা করব তার মহান রাজ্য থেকে। হারা আর উড়িয়ে দিয়ে সে যেতে রাজি হবে। পবিত্র পিতার ঈশ্বর, যিনি সে, আর আমি তাকে উড়িয়ে দিব এবং সে মারা যাবে। তাকে উড়িয়ে দাও.","‏ ‏حَدَّثَنَا ‏ ‏قُرَادٌ أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏بِأَيِّ شَيْءٍ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتَتِحُ صَلَاتَهُ إِذَا قَامَ مِنْ اللَّيْلِ قَالَتْ كَانَ إِذَا قَامَ كَبَّرَ وَيَقُولُ ‏ ‏اللَّهُمَّ رَبَّ ‏ ‏جِبْرِيلَ ‏ ‏وَمِيكَائِيلَ ‏ ‏وَإِسْرَافِيلَ ‏ ‏فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ اهْدِنِي لِمَا اخْتَلَفْتُ فِيهِ مَنْ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ قَالَ ‏ ‏يَحْيَى ‏ ‏قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ يَقُولُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْثِهِ وَنَفْخِهِ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ تَعَوَّذُوا بِاللَّهِ مِنْ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْخِهِ وَنَفْثِهِ قَالُوا يَا رَسُولَ اللَّهِ وَمَا هَمْزُهُ وَنَفْخُهُ وَنَفْثُهُ قَالَ أَمَّا هَمْزُهُ فَهَذِهِ ‏ ‏الْمُوتَةُ الَّتِي تَأْخُذُ بَنِي ‏ ‏آدَمَ ‏ ‏وَأَمَّا نَفْخُهُ فَالْكِبْرُ وَأَمَّا نَفْثُهُ فَالشِّعْرُ ‏","","",""],[24069,24069,"","আমরা আপনার টাকা নিয়ে কথা বলেছি, ঈশ্বরের ভালবাসা ভুলে যান, কিন্তু ভালবাসা গড়ে উঠেছে। আমি এমন একজনকে জিজ্ঞাসা করবো যে তার কাছে ঈশ্বরের কাছে প্রার্থনা করবে এবং সে লর্ডের প্রভু হবে এবং আমি তাকে দেব লর্ডের কাছে আমি শুনেছি... ...আর আমি তার কাছে ঋণী... ...আর আমি তার কাছে প্রার্থনা করছি যে আমি কাপুরুষের মত, আর আমি অহংকারের পাত্র। তুমি এসেছ তোমার কাছে। পাপ আমাকে মেরে ফেললে, আমি তোমাকে মেরে ফেলবো, আর আমি জানি আমি কী রক্ষা করছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَائِمٌ عَلَى الْبَابِ وَأَنَا أَسْمَعُ قَالَ أُصْبِحُ جُنُبًا وَأَنَا أُرِيدُ الصَّوْمَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أُصْبِحُ جُنُبًا وَأَنَا أُرِيدُ الصَّوْمَ قَالَ الرَّجُلُ إِنِّي لَسْتُ كَمِثْلِكَ أَنْتَ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ فَغَضِبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي أَرْجُو أَنْ أَكُونَ ‏ ‏أَخْشَاكُمْ لِلرَّبِّ عَزَّ وَجَلَّ وَأَعْلَمَكُمْ بِمَا ‏ ‏أَتَّقِي ‏","","",""],[24070,24070,"","আমি আমার বাবার ছেলের কথা বলেছিলাম ঈশ্বরের প্রেমে শপথ নিয়ে। আমি কখনোই বলিনি যে, আমার ছেলে তার কাছে প্রার্থনা করবে। এবং নামাযীদের সাথে","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نِيَارٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِظَبْيَةِ ‏ ‏خَرَزٍ ‏ ‏فَقَسَمَهَا لِلْحُرَّةِ وَلِلْأَمَةِ ‏ ‏وَقَالَتْ ‏ ‏كَانَ أَبِي يَقْسِمُ لِلْحُرِّ وَالْعَبْدِ ‏","","",""],[24071,24071,"","আমরা একটা জীবন নিয়ে কথা বলছিলাম, যে কিনা চুপ করে থাকতে চেয়েছিল, আল্লাহ তাকে জানেন আর সে চুমু খাবে আর সে একজন বিজয়ী... ...কিন্তু সে আশা করছিল যে তুমি তাকে ফিরিয়ে আনতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ وَلَكِنَّهُ كَانَ أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏","","",""],[24072,24072,"","আমরা তার বাবার সাথে কথা বলেছি... ...আমি বলতে চাচ্ছিলাম যে এটা হবে না, ঈশ্বর বলতেই হবে যে এটা এমন হবে... ...যে হয়ত তোমার মতো অভিনয় করছিল। খবর হচ্ছে যে সে বড় হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَمَثَّلُ شَيْئًا مِنْ الشِّعْرِ قَالَتْ قَدْ كَانَ ‏ ‏يَتَمَثَّلُ مِنْ شِعْرِ ‏ ‏عَبْدِ اللَّهِ بْنِ رَوَاحَةَ ‏ ‏وَيَقُولُ ‏ ‏وَيَأْتِيكَ بِالْأَخْبَارِ مَنْ لَمْ ‏ ‏تُزَوِّدِ ‏","","",""],[24073,24073,"","আপনার খেলার কথা বলছিলাম মানে আমার মা আমাকে একটা কাঠের কথা বলেছিল। লর্ড তার কাছে প্রার্থনা করল এবং আমি আমার বাসায় প্রার্থনা করব যেন আমি হাঁটু গেড়ে বসাতে পারি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏أَخْبَرَتْنِي ‏ ‏أُمِّي ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي مِنْ الضُّحَى أَرْبَعَ رَكَعَاتٍ ‏","","",""],[24074,24074,"","ঈশ্বরের দোহাই দিয়ে আমরা সবাই মহান ঈশ্বরের কাছে জয় করতে পেরেছি, ঈশ্বরের দোহাইর কাছে প্রার্থনা করেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং যে অন্য মানুষদের কাছে তিনি আত্মসমর্পণ করবেন তাদের কাছে যারা বলে যে তারা পবিত্র বাবা, আমি কে, আর দ্বিতীয়টা দ্বিতীয় আর তৃতীয়টা","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ النَّاسِ خَيْرٌ قَالَ ‏ ‏الْقَرْنُ ‏ ‏الَّذِينَ أَنَا فِيهِ ثُمَّ الثَّانِي ثُمَّ الثَّالِثُ ‏","","",""],[24075,24075,"","আমরা কিছু হাস্যরসের পরিবর্তন নিয়ে কথা বলেছি, আমি শুনেছি লর্ডের কাছে প্রার্থনা আছে তিনি মুক্তি পেয়েছেন এবং বলেছেন যে তিনি খুশি হতে চান।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَا يَنْبَغِي لِأَحَدٍ أَنْ يَبْغُضَ ‏ ‏أُسَامَةَ ‏ ‏بَعْدَمَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُحِبُّ اللَّهَ ‏ ‏عَزَّ وَجَلَّ وَرَسُولَهُ فَلْيُحِبَّ ‏ ‏أُسَامَةَ ‏","","",""],[24076,24076,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং কেবল আমাদের কোনো জল বা জল নেই । পানি.","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَإِنَّا لَجُنُبَانِ وَلَكِنَّ الْمَاءَ لَا يَجْنُبُ ‏","","",""],[24077,24077,"","আমরা একজন সাক্ষীর কথা বলেছি যে ঈশ্বরকে জিজ্ঞেস করবে, সে দুনিয়া থেকে কি পাবে আর তার কোন দরকার হবে না।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَثُرَتْ ذُنُوبُ الْعَبْدِ وَلَمْ يَكُنْ لَهُ مَا يُكَفِّرُهَا مِنْ الْعَمَلِ ابْتَلَاهُ اللَّهُ عَزَّ وَجَلَّ بِالْحُزْنِ لِيُكَفِّرَهَا عَنْهُ ‏","","",""],[24078,24078,"","আমরা একজন বৃদ্ধ প্রেমিকের চেয়ে ভালো ছেলের কথা বলেছি, সে বলেছে তার জন্য প্রার্থনা করা হয়েছে আর এক মাস আগে মেয়র কাজ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا صَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا كَامِلًا مُنْذُ قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏إِلَّا رَمَضَانَ ‏","","",""],[24079,24079,"","আমরা একটি সাহসী পুত্র আমাকে একটি ভাল নাম দিতে বলেন. এবং আমি নীরবতা অথবা নীরবতা হল হল হল হল উলালগাহ. তিনি সকালে আমাদের বললেন তিনি পাবেন ঈশ্বরের মায়েরা, কখনো তার কথা শুনবে না। সম্ভবত লর্ড লর্ড লর্ড তাকে আদেশ দিয়েছেন, ঈশ্বর কখনো তাকে আদেশ দেন না আর তার সাথে আছেন। সময়ের সাথে সাথে আত্মসমর্পণ করবে, যখন ঈশ্বর বিশ্রাম নিবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏كُنَّا مُسْتَنِدَيْنِ إِلَى الْحُجْرَةِ وَأَنَا أَسْمَعُ صَوْتَ السِّوَاكِ ‏ ‏أَوْ سِوَاكَهَا ‏ ‏وَهِيَ ‏ ‏تَسْتَنُّ ‏ ‏قُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجَبٍ قَالَ نَعَمْ قُلْتُ يَا ‏ ‏أُمَّ الْمُؤْمِنِينَ ‏ ‏أَلَا تَسْتَمِعِينَ مَا يَقُولُ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَتْ وَمَا يَقُولُ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ يَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَمَرَ فِي رَجَبٍ قَالَتْ يَغْفِرُ اللَّهُ ‏ ‏لِأَبِي عَبْدِ الرَّحْمَنِ ‏ ‏وَاللَّهِ ‏ ‏مَا اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عُمْرَةٍ ‏ ‏أَوْ عُمْرَةً ‏ ‏إِلَّا ‏ ‏وَأَبُو عَبْدِ الرَّحْمَنِ ‏ ‏مَعَهُ وَمَا اعْتَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجَبٍ ‏","","",""],[24080,24080,"","আমরা খুশি হয়েছি বেঁচে থাকার ভয় পাওয়ার চেয়ে ভালো কথা বলে, সে চলে গেছে, আমরা ওক গাছের সাথে কাজ করছি।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ مَسْعَدَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏التَّبَتُّلِ ‏","","",""],[24081,24081,"","আমরা বিয়ের ব্যাপারে কথা বলেছিলাম, আমি বসে ঈশ্বরের দোহাই বসে কথা বলব।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏قَالَ ‏ ‏قَالَتْ لِي ‏ ‏عَائِشَةُ ‏ ‏أَلَا يُعْجِبُكَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏جَاءَ فَجَلَسَ إِلَى جَانِبِ حُجْرَتِي يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْمِعُنِي ذَلِكَ وَكُنْتُ أُسَبِّحُ فَقَامَ قَبْلَ أَنْ أَقْضِيَ سُبْحَتِي لَوْ جَلَسَ حَتَّى أَقْضِيَ سُبْحَتِي لَرَدَدْتُ عَلَيْهِ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يَسْرُدُ الْحَدِيثَ كَسَرْدِكُمْ ‏","","",""],[24082,24082,"","আমরা বাবার কথা বলেছিলাম তোমার উপর শপথ নিয়ে। সে বলল, সে তার কাছে প্রার্থনা করেছে যেন সে তার কাছে প্রার্থনা করে যে তারা সব এলাকা মেরে ফেলবে। যে ছেলেটাকে মেরে ফেলবে... ...যে তোমাকে মেরে ফেলবে তার সাথে প্রতারণা করবে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا الْحَيَّاتِ كُلَّهُنَّ إِلَّا الْجَانَّ ‏ ‏الْأَبْتَرَ ‏ ‏مِنْهَا ‏ ‏وَذَا الطُّفْيَتَيْنِ ‏ ‏عَلَى ظَهْرِهِ فَإِنَّهُمَا يَقْتُلَانِ الصَّبِيَّ فِي بَطْنِ أُمِّهِ وَيُغَشِّيَانِ الْأَبْصَارَ مَنْ تَرَكَهُمَا فَلَيْسَ مِنَّا ‏","","",""],[24083,24083,"","বাবা তাকে একটা জীবন্ত জীবন দেওয়ার কথা বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করেছিলেন আর আমি তার প্রয়োজন এবং জনতার চিন্তাও পূরণ করতাম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[24084,24084,"","তিনি বলেছিলেন যে, ঈশ্বর তার জন্য প্রার্থনা করেন এবং কুকুরকে প্রভুর কাছে সমর্পণ করেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَلْبُ الْأَسْوَدُ الْبَهِيمُ شَيْطَانٌ ‏","","",""],[24085,24085,"","বাবা যখন কথা বলছিল, তখন আমরা বাবার সাথে কথা বলেছি, আমি তার সাথে কথা বলেছি এবং তার মেয়েদের সাথে কথা বলেছি। ভীতির সাথে হত্যা হচ্ছে এই মৃত্যুর ভয় জীবনের মানুষ। সে তাদের সাথে সারাদিন কথা বলত এবং যখন মানুষ তাকে দেখে তখন সে বলে \"ভাল\"। ঠিক মত অবস্থান আমি ঈশ্বরের পুত্রকে বলি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَقِيلٍ يَعْنِي الثَّقَفِيَّ ‏ ‏حَدَّثَنَا ‏ ‏مُجَالِدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏حَدَّثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ ذَاتَ لَيْلَةٍ حَدِيثًا فَقَالَتْ امْرَأَةٌ مِنْهُنَّ يَا رَسُولَ اللَّهِ كَانَ الْحَدِيثُ حَدِيثَ ‏ ‏خُرَافَةَ ‏ ‏فَقَالَ ‏ ‏أَتَدْرُونَ مَا ‏ ‏خُرَافَةُ ‏ ‏إِنَّ ‏ ‏خُرَافَةَ ‏ ‏كَانَ رَجُلًا مِنْ ‏ ‏عُذْرَةَ ‏ ‏أَسَرَتْهُ الْجِنُّ فِي الْجَاهِلِيَّةِ فَمَكَثَ فِيهِنَّ دَهْرًا طَوِيلًا ثُمَّ رَدُّوهُ إِلَى الْإِنْسِ فَكَانَ يُحَدِّثُ النَّاسَ بِمَا رَأَى فِيهِمْ مِنْ الْأَعَاجِيبِ فَقَالَ النَّاسُ حَدِيثُ ‏ ‏خُرَافَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَبُو عَقِيلٍ ‏ ‏هَذَا ثِقَةٌ اسْمُهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَقِيلٍ الثَّقَفِيُّ ‏","","",""],[24086,24086,"","আমরা তার মায়ের কথা বলেছিলাম, ঈশ্বরের প্রার্থনা তিনি মানুষের শান্তি ফিরিয়ে দেবেন ষড়যন্ত্র আর পানি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏دَوُادُ يَعْنِي الْعَطَّارَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ شَبِعَ النَّاسُ مِنْ الْأَسْوَدَيْنِ التَّمْرِ وَالْمَاءِ ‏","","",""],[24087,24087,"","আমরা তার মায়ের সঙ্গে বাস করতাম বলে আমরা তার কথা বলেছিলাম, তিনি বলেছিলেন । একটি গ্রীষ্মের ছেলে হিসেবে... ...তার মায়ের ভবিষ্যৎ নিয়ে ভবিষ্যদ্বাণী করার জন্য.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَّكِئُ فِي حِجْرِي وَأَنَا حَائِضٌ يَقْرَأُ الْقُرْآنَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏دَوُادُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[24088,24088,"","বাবার বাবার ছেলের কথা বলেছিলাম, বাবা যা চাচ্ছে, আমি তাকে বললাম, কেন সে আমাকে ঈশ্বরের অনুগ্রহে স্পর্শ করবে। সে তার প্রার্থনার সময় জীবন নিয়ে নিয়েছে। এরপর তিনি শপথ করে বলেছিলেন যে, তিনি যেভাবে করেছিলেন, সেভাবে চলে গিয়েছেন এবং তারপর তিনি যেভাবে সৃষ্টি করেছিলেন, সেভাবে চলে গিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي حَفْصَةَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرْتْهُ ‏ ‏لَمَّا كَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَأَمَرَ فَنُودِيَ أَنَّ الصَّلَاةَ ‏ ‏جَامِعَةٌ ‏ ‏فَقَامَ فَأَطَالَ الْقِيَامَ فِي صَلَاتِهِ ‏ ‏قَالَ فَأَحْسِبُهُ قَرَأَ سُورَةَ ‏ ‏الْبَقَرَةِ ‏ ‏ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ثُمَّ قَامَ مِثْلَ مَا قَامَ وَلَمْ يَسْجُدْ ثُمَّ رَكَعَ فَسَجَدَ ثُمَّ قَامَ فَصَنَعَ مِثْلَ مَا صَنَعَ ثُمَّ رَكَعَ رَكْعَتَيْنِ فِي سَجْدَةٍ ثُمَّ جَلَسَ وَجُلِّيَ عَنْ الشَّمْسِ ‏","","",""],[24089,24089,"","বাবার সাথে যৌন সম্পর্ক স্থাপনের কথা বলেছিলাম, সে যদি হাঙ্গর নেয়... ...তাহলে সে তাকে বলবে যে সে ঈশ্বরের দুঃখ আর তার জীবনের সাথে কী সম্পর্ক করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا فَقَالَ ‏ ‏لَوْلَا أَنْ ‏ ‏تَبْطَرَ ‏ ‏قُرَيْشٌ ‏ ‏لَأَخْبَرْتُهَا بِمَا لَهَا عِنْدَ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[24090,24090,"","আমরা আমাদের বাপ্তিস্মকে রক্ষা করার চেষ্টা করেছি... ...আমাদের জীবন নিয়ে... ...ঈশ্বর তোমার আত্মাকে পাপ করেছেন বলে যে, সে বলেছে যে, আমরা ঈশ্বরের কাছে যেতে আদেশ করেছি, তা সে উদ্ধার করতে পারবে। আর শীতের পঞ্চমাংশ থেকে পালিয়ে যেতে আদেশ করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏نُعِقَّ ‏ ‏عَنْ ‏ ‏الْجَارِيَةِ ‏ ‏شَاةً وَعَنْ الْغُلَامِ شَاتَيْنِ وَأَمَرَنَا ‏ ‏بِالْفَرَعِ ‏ ‏مِنْ كُلِّ خَمْسِ شِيَاهٍ شَاةٌ ‏","","",""],[24091,24091,"","আমরা একজন বয়ফ্রেন্ডের সাথে কথা বলেছি যে ডিনার করবে, আমি তাদের বলে দিব যে তারা এটা করবে আর আমি এটা ছেড়ে দেব। আমি ঈশ্বরের কাছে ক্ষমা চাই, আর তুমি যা চাও, তা তোমার জন্য। আমি তোমার ক্ষমা চাই। প্রভু খুব প্রিয় এবং তিনি আপনার পবিত্র স্থানে আপনার জন্য দ্রুত করছি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تُعَيِّرُ ‏ ‏النِّسَاءَ اللَّاتِي وَهَبْنَ أَنْفُسَهُنَّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ أَلَا تَسْتَحِي الْمَرْأَةُ أَنْ تَعْرِضَ نَفْسَهَا بِغَيْرِ صَدَاقٍ فَنَزَلَ ‏ ‏أَوْ قَالَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏تُرْجِي مَنْ تَشَاءُ مِنْهُنَّ وَتُؤْوِي إِلَيْكَ مَنْ تَشَاءُ وَمَنْ ابْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ‏} ‏قَالَتْ إِنِّي أَرَى رَبَّكَ عَزَّ وَجَلَّ يُسَارِعُ لَكَ فِي هَوَاكَ ‏","","",""],[24092,24092,"","আমরা এক জীবন্ত জীবনযাপনের কথা বলেছিলাম, যখন নাবিকরা স্বপ্নের মধ্যে চলে গিয়েছিল । সে যা বলেছে, সে যা বলেছে, তার জন্য মাঝে মাঝে মাঝে সে বেঁচে থাকে, আমি ভয় পাচ্ছি নাবিকের জীবন চাই, আমরা তাকে ভালোবাসি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏الْحَارِثَ بْنَ هِشَامٍ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ يَأْتِيكَ الْوَحْيُ قَالَ أَحْيَانًا يَأْتِينِي فِي مِثْلِ ‏ ‏صَلْصَلَةِ ‏ ‏الْجَرَسِ وَهُوَ أَشَدُّهُ عَلَيَّ ثُمَّ ‏ ‏يُفْصَمُ ‏ ‏عَنِّي وَقَدْ وَعَيْتُ وَأَحْيَانًا يَأْتِينِي مَلَكٌ فِي مِثْلِ صُورَةِ الرَّجُلِ فَأَعِي مَا يَقُولُ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرُ بْنُ صَالِحٍ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[24093,24093,"","আমার বাবা এমন একটা বাসা বেছে নেওয়ার জন্য একটা বাসা বেছে নেন, যেটা ঈশ্বরের জন্য সর্বোত্তম ব্যক্তি বলে দাবি করা হয় । সে ব্যর্থ হয়েছে, ঈশ্বর এটা করেছেন আর আমরা তার দশ সন্তানের কাছে হার মানব যে সে ব্যর্থ হয়েছে। আমি বলেছি, প্রভু, আপনি যা বলেছেন, তার অনুমোদন আছে, তুমি কখনোই আরেকজনকে হত্যা করতে পারো নি, যাদের অনুসন্ধানে দরকার ছিল।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏وَسُرَيْجٌ يَعْنِي ابْنَ النُّعْمَانِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اسْتَأْذَنَ رَجُلٌ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بِئْسَ ابْنُ الْعَشِيرَةِ فَلَمَّا دَخَلَ هَشَّ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَانْبَسَطَ إِلَيْهِ ثُمَّ خَرَجَ فَاسْتَأْذَنَ رَجُلٌ آخَرُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِعْمَ ابْنُ الْعَشِيرَةِ فَلَمَّا دَخَلَ لَمْ يَنْبَسِطْ إِلَيْهِ كَمَا انْبَسَطَ إِلَى الْآخَرِ وَلَمْ يَهَشَّ لَهُ كَمَا هَشَّ فَلَمَّا خَرَجَ قُلْتُ يَا رَسُولَ اللَّهِ اسْتَأْذَنَ فُلَانٌ فَقُلْتَ لَهُ مَا قُلْتَ ثُمَّ هَشَشْتَ لَهُ وَانْبَسَطْتَ إِلَيْهِ وَقُلْتَ لِفُلَانٍ مَا قُلْتَ وَلَمْ أَرَكَ صَنَعْتَ بِهِ مَا صَنَعْتَ لِلْآخَرِ فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ مِنْ شِرَارِ النَّاسِ مَنْ اتُّقِيَ لِفُحْشِهِ ‏","","",""],[24094,24094,"","আমরা এক বছর ধরে এক ছেলের কথা বলেছিলাম যে এক বছর সুখী হবে. তারপর সে চলে যায়, সে বলে নি, \"মানুষ কি বলছে সে সেই নয় যে সে নয় যিনি সেই নয়। যে ই না এই ব্যক্তি যে... ...সে... ...তবুও যে তোমাকে কষ্ট দেবে তার জন্য, তোমার ফোন করার আগে এটা ঘৃণা করত. আমি যদি তোমাকে জিজ্ঞেস করি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَرَفْتُ فِي وَجْهِهِ أَنْ قَدْ ‏ ‏حَفَزَهُ ‏ ‏شَيْءٌ فَتَوَضَّأَ ثُمَّ خَرَجَ فَلَمْ يُكَلِّمْ أَحَدًا ‏ ‏فَدَنَوْتُ ‏ ‏مِنْ الْحُجُرَاتِ فَسَمِعْتُهُ يَقُولُ يَا أَيُّهَا النَّاسُ إِنَّ اللَّهَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏مُرُوا بِالْمَعْرُوفِ وَانْهَوْا عَنْ الْمُنْكَرِ مِنْ قَبْلِ أَنْ تَدْعُونِي فَلَا أُجِيبُكُمْ وَتَسْأَلُونِي فَلَا أُعْطِيكُمْ وَتَسْتَنْصِرُونِي فَلَا أَنْصُرُكُمْ ‏","","",""],[24095,24095,"","সেই সময় আমি আমার বাবার সঙ্গে আমার প্রেমের বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ عِيسَى ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ بْنَ الْحَجَّاجِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نُعَيْمِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏صَلَّى بِالنَّاسِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الصَّفِّ ‏","","",""],[24096,24096,"","আমরা একজন যুবকের কথা বলেছি যে আমাদের পিতা হওয়ার কথা বলেছে, সে বলল, তার কাছে প্রার্থনা করা উচিত এবং তার নিজের বাবার স্মৃতি সমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ بْنُ سَوَّارٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَاعِدًا فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ ‏","","",""],[24097,24097,"","বিয়ের পর আমি এক উত্তম সময় সম্বন্ধে কথা বলেছিলাম । আপনার ক্লাস তাকে ঈশ্বরের জন্য উত্তম কিছু বলতে শিক্ষা দেয় ।","‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏يُصَلِّي بِالنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ ‏ ‏أَسِيفٌ ‏ ‏فَمَتَى يَقُومُ مَقَامَكَ تُدْرِكُهُ الرِّقَةُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُنَّ صَوَاحِبُ ‏ ‏يُوسُفَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَصَلَّى ‏ ‏أَبُو بَكْرٍ ‏ ‏وَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفَهُ قَاعِدًا ‏","","",""],[24098,24098,"","আমরা দামের জন্য অনুসন্ধানের বিষয়ে ১২টা কথা বলেছিলাম । এই ধরনের আশীর্বাদের মধ্যে দিয়ে প্রতিবেশীদের সুস্থ করা এবং সুস্থ করার জন্য আরও ভাল হয়, রক্তকে প্রসারিত করা ও সন্তাপের বৃদ্ধি করা ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مِهْزَمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏إِنَّهُ مَنْ أُعْطِيَ حَظَّهُ مِنْ الرِّفْقِ فَقَدْ أُعْطِيَ حَظَّهُ مِنْ خَيْرِ الدُّنْيَا وَالْآخِرَةِ وَصِلَةُ الرَّحِمِ وَحُسْنُ الْخُلُقِ وَحُسْنُ الْجِوَارِ يَعْمُرَانِ الدِّيَارَ وَيَزِيدَانِ فِي الْأَعْمَارِ ‏","","",""],[24099,24099,"","আমরা আমার ছেলেকে তার জীবন নিয়ে কথা বলেছি, ঈশ্বরের কাছে আছে এবং সে বলবে সে সন্ধ্যার জন্য বিশ্বের সেরা নারীদের জন্য ব্যয় করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَضْلُ ‏ ‏عَائِشَةَ ‏ ‏عَلَى النِّسَاءِ كَفَضْلِ ‏ ‏الثَّرِيدِ ‏ ‏عَلَى الطَّعَامِ ‏","","",""],[24100,24100,"","ঈশ্বরের কাছে প্রার্থনা করার পর, আমি তাকে একটা বিষয়ে শিক্ষা দেওয়ার জন্য ঈশ্বরের কাছে আদেশ দিয়েছি ঈশ্বরের দাস, আমার বাবা স্বাধীন হওয়ার শপথ করত এবং খেলাধুলা করত, আমার বাবা একজন যাজকের চেয়ে বেশি কিছু ।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ نِيَارٍ الْأَسْلَمِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِظَبْيَةٍ ‏ ‏فِيهَا خَرَزٌ فَقَسَمَ لِلْحُرَّةِ وَالْأَمَةِ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏وَكَانَ أَبِي يَقْسِمُ لِلْحُرِّ وَالْعَبْدِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏فَقَسَمَ بَيْنَ الْحُرَّةِ وَالْأَمَةِ سَوَاءً ‏","","",""],[24101,24101,"","আমরা কথা বলেছি সবচেয়ে ছোট জিনিস সম্পর্কে জানতে সাহায্য করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَاتَانِ لَمْ يَتْرُكْهُمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِرًّا وَلَا عَلَانِيَةً رَكْعَتَيْنِ بَعْدَ الْعَصْرِ وَرَكْعَتَيْنِ قَبْلَ الْفَجْرِ ‏","","",""],[24102,24102,"","আমরা আমাদের সাথে লড়াই করার মাধ্যমে আমাদের টাকা সঞ্চয়ের কথা বলেছিলাম। ঈশ্বর আমাকে যা বলতে যাচ্ছেন, সে ই হচ্ছে আমার জয় চুরি করেছে এবং সে আমার হাতুড়ি চুরি করেছে এবং সে ভয় পাচ্ছে, আল্লাহ আমাদের উপর আস্থা রাখে। আমি যদি যুদ্ধ করি, তাহলে আমরা আমাদের টাকা বাঁচাব। আমি যা বলবো, তা হবে, আমরা যদি আমাদের টাকা বাঁচাব, তাহলে আমরা শুধু একটা স্বপ্ন দেখতে পাব। কিন্তু আমরা যদি আমাদের টাকা চুরি করব, তাহলে আমরা কি করবো? কিন্তু, কখনো না, আমার বাবা এতই ভাল হবেন যে, তিনি বিশ্বাস করেন যে, ঈশ্বর জয়ী হয়েছেন এবং এর ফলে এক পার্থক্য গড়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ مِغْوَلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَعِيدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ فِي هَذِهِ الْآيَةِ ‏ { ‏الَّذِينَ يُؤْتُونَ مَا آتَوْا وَقُلُوبُهُمْ وَجِلَةٌ أَنَّهُمْ إِلَى رَبِّهِمْ رَاجِعُونَ ‏} ‏يَا رَسُولَ اللَّهِ هُوَ الَّذِي يَسْرِقُ ‏ ‏وَيَزْنِي وَيَشْرَبُ الْخَمْرَ وَهُوَ يَخَافُ اللَّهَ قَالَ لَا يَا ‏ ‏بِنْتَ أَبِي بَكْرٍ ‏ ‏يَا ‏ ‏بِنْتَ الصِّدِّيقِ ‏ ‏وَلَكِنَّهُ الَّذِي ‏ ‏يُصَلِّي وَيَصُومُ وَيَتَصَدَّقُ وَهُوَ يُخَافُ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[24103,24103,"","আমরা একটা ছেলের কথা বলেছিলাম যে সে আমার বাবার মত আমাকে শুনতে পেয়েছে, আমাকে বলা হয়েছে যে আমি তার কাছে কৃতজ্ঞ যে তাকে ঈশ্বরের কাছে পাঠানো হবে. তার পালক বলে যে যদি আমরা তাকে খুঁজে পেতাম, শিকারীরা তাদের থেকে শক্তিশালী হচ্ছে, এবং এটা সবসময় তোমার স্বাদের কোন পাপ নয়.","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ يَعْنِي ابْنَ سَلَّامٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ شَيْبَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَرَقَهُ وَجَعٌ فَجَعَلَ يَشْتَكِي وَيَتَقَلَّبُ عَلَى فِرَاشِهِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَوْ صَنَعَ هَذَا بَعْضُنَا لَوَجِدْتَ عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الصَّالِحِينَ يُشَدَّدُ عَلَيْهِمْ وَإِنَّهُ لَا يُصِيبُ مُؤْمِنًا نَكْبَةٌ مِنْ شَوْكَةٍ فَمَا فَوْقَ ذَلِكَ إِلَّا حُطَّتْ بِهِ عَنْهُ خَطِيئَةٌ وَرُفِعَ بِهَا دَرَجَةً ‏","","",""],[24104,24104,"","আমরা এই বেঁচে থাকার কথা বলেছিলাম, ঈশ্বর তাকে শান্তি দেবেন... ...সে তার হাত তুলে দেবে... ...আর লর্ডকে ডাক দেবে যখন আমি খারাপ হয়ে যাব.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ يَدْعُو حَتَّى أَسْمَعَ ‏ ‏اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ فَلَا تُعَاقِبْنِي بِشَتْمِ رَجُلٍ مِنْ الْمُسْلِمِينَ إِنْ آذَيْتُهُ ‏","","",""],[24105,24105,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং আমার বাড়িতে ও রাতে আমার বাড়িতে সাহায্য করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ شَرِيكٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي وَفِي لَيْلَتِي ‏","","",""],[24106,24106,"","আমরা আমার বাবার কথা বলেছিলাম যে আমরা তার জীবন নিয়ে কথা বলেছি, ঈশ্বর তাকে এমন কিছু ছেড়ে দিতে বলেছেন যা সে দিয়ে যাচ্ছে, আর তোমার উপর আমার চোখ দিয়ে তুমি চিন্তা করো না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ شَرِيكٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ شَيْءٍ مِنْ أَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏فَذَكَرَتْ شَيْئًا قَلِيلًا فَقَالَ لَهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطِي وَلَا ‏ ‏تُوعِي ‏ ‏فَيُوعَى ‏ ‏عَلَيْكِ ‏","","",""],[24107,24107,"","বাবা আমাদের কথা বলেছিলাম আমরা যেন ঈশ্বরের কাছে তার মায়ের বাসার অন্য দিকে যাই। ভগবান তার জন্য প্রার্থনা করে। আর উনি বলেন, বিক্রি না করতে না যেতে। আমার বাবার জীবনের ভুলের হাত থেকে বেঁচে যাবার তৃতীয় রাস্তা।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَارِجَةُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُبَاعُ الثَّمَرَةُ حَتَّى تَنْجُوَ مِنْ ‏ ‏الْعَاهَةِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏خَارِجَةُ ‏ ‏ضَعِيفُ الْحَدِيثِ ‏","","",""],[24108,24108,"","আমরা বাবার সাথে কথা বলেছিলাম যে আমি অনেক বৃদ্ধ, তার জন্য প্রার্থনা করি আর আয়নায় সে কি বলবে, তা দেখে সে আত্মসমর্পণ করবে। পুতুল.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أُمَّ بَكْرٍ ‏ ‏أَخْبَرَتْهُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي الْمَرْأَةِ ‏ ‏تَرَى مَا ‏ ‏يُرِيبُهَا ‏ ‏بَعْدَ الطُّهْرِ قَالَ إِنَّمَا هُوَ عُرُوقٌ ‏ ‏أَوْ قَالَ عِرْقٌ ‏","","",""],[24109,24109,"","বাবা আমাদের দশ বছর ধরে রক্ষা করার চেষ্টা করছেন বলে আমরা বাবা সম্বন্ধে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الَّذِينَ يَصِلُونَ الصُّفُوفَ ‏","","",""],[24110,24110,"","আমরা আদালতে আমার বাবার সাথে কথা বলেছি যে আমি এটা শুনেছি। একটি চিত্রায়ন দেখা যাচ্ছে, যখন ভবিষ্যদ্বাণীর ঘরে আসা সমবেদনা ঈশ্বরের কাছে এসেছে এবং তার জন্য। একজন ব্যক্তি কখনোই নীরব ও নীরব সেবার প্রতি আগ্রহ দেখাননি । ঈশ্বর পাপ ক্ষমা করুন, আর শেষ পর্যন্ত যেতে হবে না। আর ওর আবেগ আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِسْحَاقَ بْنَ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَيْبَةُ الْخُضْرِيُّ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَجْعَلُ اللَّهُ عَزَّ وَجَلَّ رَجُلًا لَهُ سَهْمٌ فِي الْإِسْلَامِ كَمَنْ لَا سَهْمَ لَهُ قَالَ وَسِهَامُ الْإِسْلَامِ الصَّوْمُ وَالصَّلَاةُ ‏ ‏وَالصَّدَقَةُ ‏ ‏وَلَا يَتَوَلَّى اللَّهُ عَزَّ وَجَلَّ رَجُلًا فِي الدُّنْيَا فَيُوَلِّيَهُ يَوْمَ الْقِيَامَةِ غَيْرَهُ وَلَا يُحِبُّ رَجُلٌ قَوْمًا إِلَّا جَاءَ مَعَهُمْ يَوْمَ الْقِيَامَةِ قَالَ وَالرَّابِعَةُ لَا يَسْتُرُ اللَّهُ عَزَّ وَجَلَّ عَلَى عَبْدٍ ذَنْبًا فِي الدُّنْيَا إِلَّا سَتَرَهُ عَلَيْهِ فِي الْآخِرَةِ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏إِذَا سَمِعْتُمْ مِثْلَ هَذَا الْحَدِيثِ مِنْ مِثْلِ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحْفَظُوهُ ‏","","",""],[24111,24111,"","আমরা এমন এক রাজার কথা বলেছি, যারা এক দেবতাের পুত্র ছিল. নাম হল... ...যেন সব ঋণ থেকে তোমাকে বের করে... ...যে তোমার কাছে আসে, তাই সে আমার সব হিংসাকে ঘৃণা করে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَكَى رَقَاهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ ‏ ‏بِسْمِ اللَّهِ ‏ ‏أَرْقِيكَ مِنْ كُلِّ دَاءٍ ‏ ‏يَشْفِيكَ مِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ وَمِنْ شَرِّ كُلِّ ذِي عَيْنٍ ‏","","",""],[24112,24112,"","তিনি তার সঙ্গে ঈশ্বরকে পাঠানোর বিষয়ে কথা বলেছিলেন এবং তিনি তাকে কখনও দেখতে পাননি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏أُمُّ مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَرْقُدُ مِنْ لَيْلٍ وَلَا نَهَارٍ فَيَسْتَيْقِظُ إِلَّا اسْتَاكَ قَبْلَ الْوُضُوءِ ‏","","",""],[24113,24113,"","আমি আমার বাবার কথা বলেছি আমাদের হত্যা করার চেষ্টা করার ব্যাপারে। আমি বেঁচে ছিলাম আল্লাহ তার কাছে প্রার্থনা করে... ...আর তাকে আমার কাছে পৌঁছে দেয়া হবে যারা পরাজিত হবে।","‏ ‏أَحْمَدُ بْنُ حَنْبَلٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرَى مِنْ يَهُودِيٍّ طَعَامًا فَرَهَنَهُ دِرْعَهُ ‏","","",""],[24114,24114,"","আমি একটা বোতাম জেনে আটকে ছিলাম আর তারপর আমি ভাববাদীর সাথে যাব, ঈশ্বর তাকে শিখিয়েছিলেন আর তার চুল আর চুলের স্বপ্নও থাকবে সে তার প্রেমে পড়েছিলো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ إِذَا ‏ ‏طَمِثْتُ ‏ ‏شَدَدْتُ عَلَيَّ ‏ ‏إِزَارًا ‏ ‏ثُمَّ أَدْخُلُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شِعَارَهُ وَلَكِنَّهُ كَانَ أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏","","",""],[24115,24115,"","আমরা দুটো গ্রাম তৈরি করেছি যেগুলো আমার বাবার ছেলে বহু বছর আগে একটা ছায়ার জন্য যাচ্ছে, ঈশ্বর দুই শতাব্দী ধরে অন্ধকারের শপথ নিয়ে এসেছেন। এক বছরের ভবিষ্যদ্বাণীর কথা, ম্যাচটা শেষ হয়ে গেছে এবং তোমার ছেলে যখন জন্ম হয়েছিল তখন সে মারা যায়।","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مَخْلَدِ بْنِ خُفَافٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْغَلَّةَ بِالضَّمَانِ ‏ ‏سَمِعْتُ مِنْ ‏ ‏قُرَّانَ بْنِ تَمَّامٍ ‏ ‏فِي سَنَةِ إِحْدَى وَثَمَانِينَ وَمِائَةٍ وَكَانَ ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏بَاقِيًا وَفِيهَا مَاتَ ‏ ‏ابْنُ الْمُبَارَكِ ‏","","",""],[24116,24116,"","আমরা আমাদের অতিথির সাথে ডিনারের জন্য অনুমতি নিয়ে কথা বলেছি, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং একটি আলো থেকে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَهُوَ بَيْنَهُمَا ‏","","",""],[24117,24117,"","আমরা দুটো উপায় নিয়ে কথা বলেছি যে আমরা বাবাকে দেখাতে যাচ্ছি, আমি অন্য জাদুর সাথে এটা লিখেছি, আমার প্রভুর কাছে আছে এটা ছেড়ে দিয়ে জিজ্ঞাসা","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا ‏ ‏أَلْفِيتُهُ ‏ ‏بِالسَّحَرِ الْآخِرِ إِلَّا نَائِمًا عِنْدِي تَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24118,24118,"","আমরা একটা বিষয় নিয়ে কথা বলেছি, কিন্তু আমরা এই বিষয়ে কথা বলেছি। এমনকি যদি নবী তার কাছে প্রার্থনা করেও, সে ঈশ্বরের এক নারীকে প্রবেশ করবে এবং সে বুড়ো হয়ে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ جَمِيلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى امْرَأَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَفِي الْبَيْتِ ‏ ‏قِرْبَةٌ ‏ ‏مُعَلَّقَةٌ ‏ ‏فَاخْتَنَثَهَا ‏ ‏وَشَرِبَ وَهُوَ قَائِمٌ ‏","","",""],[24119,24119,"","আমরা লর্ড বেনের সাথে কথা বলেছি, দিনের দশম বার্ষিকী ছিল, আমি ঈশ্বরের কাছে প্রার্থনা করছি তার শান্তির জন্য আর তারপর সে বলবে যে আমাদের পরে জামা পরে আছে।","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أُدْرِجَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَوْبٍ ‏ ‏حِبَرَةٍ ‏ ‏ثُمَّ أُخِذَ عَنْهُ ‏ ‏قَالَ ‏ ‏الْقَاسِمُ ‏ ‏إِنَّ بَقَايَا ذَلِكَ الثَّوْبِ لَعِنْدَنَا بَعْدُ ‏","","",""],[24120,24120,"","আমরা একটি শান্তি সঙ্গে একটি ছেলে কথা বলেছি যে আমরা আমার জীবনের সবচেয়ে খারাপ কাজ করেছি. লর্ড প্রার্থনা করেছিলেন তার কাছে প্রার্থনা করেছিলেন এবং তাকে আত্মসমর্পণ করবেন যদি খান বিশ্বাসঘাতকদের হারা দিত এবং তাকে ক্ষমা করতে হত. আমরা পৌঁছে গেছি এবং আমাদের জিজ্ঞাসা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏إِذَا ‏ ‏جَاوَزَ ‏ ‏الْخِتَانُ ‏ ‏الْخِتَانَ ‏ ‏فَقَدْ وَجَبَ الْغُسْلُ فَعَلْتُهُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاغْتَسَلْنَا ‏","","",""],[24121,24121,"","আমরা সবাই আমার ভালবাসার অন্ত্যেষ্টিক্রিয়ার খরচের চেয়ে ভাল ছিলাম, সে তার জন্য প্রার্থনা করতে গিয়েছিল আর তার চোরদের ভাগ্যের মধ্যে দিয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏وَابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمُرُّ بِالْقِدْرِ فَيَأْخُذُ الْعَرْقَ فَيُصِيبُ مِنْهُ ثُمَّ ‏ ‏يُصَلِّي وَلَمْ يَتَوَضَّأْ وَلَمْ يَمَسَّ مَاءً ‏","","",""],[24122,24122,"","আমি আমার কাছে এর চেয়ে ভাল কিছু করেছি, আমাকে এটা বিক্রি করতে হবে আর সেটা আবার চালু করতে হবে, সে সেখানে প্রবেশ করার আগে সে পানি প্রবেশ করবে তারপর সে তার ডান হাতের কাছে প্রবেশ করবে তিন দিন তিনি তার মুখ তুলে তার দিকে তাকিয়ে দেখেন, তারপর তিনি তার দিকে তিন সেন্ট ছুড়ে ফেলেন এবং তিনি জয়ী হন।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْنُبُ فَيُوضَعُ لَهُ الْإِنَاءُ فِيهِ الْمَاءُ فَيُفْرِغُ عَلَى يَدَيْهِ فَيَغْسِلُهَا قَبْلَ أَنْ يُدْخِلَهُمَا فِي الْمَاءِ ثُمَّ يُدْخِلُ يَدَهُ الْيُمْنَى فِي الْإِنَاءِ فَيُفْرِغُ بِهَا عَلَى يَدِهِ الْيُسْرَى فَيَغْسِلُ فَرْجَهُ ثُمَّ يُمَضْمِضُ وَيَسْتَنْشِقُ ثَلَاثًا وَيَغْسِلُ وَجْهَهُ وَذِرَاعَيْهِ ثُمَّ يَغْرِفُ ثَلَاثَ غَرَفَاتٍ فَيَصُبُّهَا عَلَى رَأْسِهِ ثُمَّ يَغْتَسِلُ ‏","","",""],[24123,24123,"","আমি যখন ঘরে ফিরে আসি, তখন আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন শুরু করি ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[24124,24124,"","আমরা তার বাবার কথা বলেছিলাম যে তিনি আমাকে ঈশ্বরের কাছে জিজ্ঞেস করতে বলেছেন আমি আপনাকে দু’বার ঘুমাতে দেখতে পাবো যখন আমি আপনাকে মুক্ত চুরি করে দেখতে পারি। এটা ঈশ্বরের সমবেদনা এবং তিনি। সামনে যাও।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُكِ فِي الْمَنَامِ مَرَّتَيْنِ أَرَى رَجُلًا يَحْمِلُكِ فِي ‏ ‏سَرَقَةِ ‏ ‏حَرِيرٍ فَيَقُولُ هَذِهِ امْرَأَتُكَ فَأَكْشِفُهَا فَإِذَا هِيَ أَنْتِ فَأَقُولُ إِنْ يَكُ هَذَا مِنْ عِنْدِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏يُمْضِهِ ‏","","",""],[24125,24125,"","আমরা তার বাবার জীবন নিয়ে তার বাবার প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি এবং ঈশ্বরের দোহাই দিয়ে তার জন্য এসেছে। তিন বার একটি হাঁটুর দশগুণ গৌরবের আংটির সাথে মিশে গেছে, এমনকি তা নয়। অন্য দিকে বসে আছি।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً وَكَانَ يُوتِرُ بِخَمْسِ سَجَدَاتٍ لَا يَجْلِسُ بَيْنَهُنَّ حَتَّى يَجْلِسَ فِي الْآخِرَةِ ثُمَّ يُسَلِّمَ ‏","","",""],[24126,24126,"","আমরা মৃত্যুর পাপের প্রতি প্রবল আগ্রহ নিয়ে কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং মুক্তির আগে আমার মূল্য আমাকে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُرْوَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَطْيَبِ مَا أَقْدِرُ عَلَيْهِ قَبْلَ أَنْ يُحْرِمَ ثُمَّ يُحْرِمُ ‏","","",""],[24127,24127,"","আমরা বাবার জীবন নিয়ে আমাদের ভয়কে কথা বলেছি, কখনো ঈশ্বরকে পাঠিও না। আমি তাদের আদেশ দিচ্ছি, তারা যেন অন্য কোথাও থেকে পালায়, সেটা না বেছে নেবার জন্য। আমার একটা ইতিহাস আছে। নিজের জন্য লড়াই করো, একটা বিড়ম্বনা আমাকে বলছে।","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ أَحَدُهُمَا أَيْسَرُ مِنْ الْآخَرِ إِلَّا اخْتَارَ أَيْسَرَهُمَا مَا لَمْ يَكُنْ إِثْمًا فَإِذَا كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قَالَ لِي ‏ ‏يَعْنِي ‏ ‏عُثْمَانَ بْنَ عُرْوَةَ ‏ ‏هِشَامٌ ‏ ‏يُخْبِرُ بِهِ عَنِّي ‏","","",""],[24128,24128,"","আমরা তাকে একজন হাঙ্গর সম্পর্কে বলতে চাই। তার মায়ের আস্থা নিয়ে বেঁচে থাকার সুযোগ আছে। সে আমাকে জিজ্ঞাসা করেছে যে, ঈশ্বরের কাছে তার পতাকা আছে এবং তাকে বলতে হবে আমি সে বলছে, আমি একজন হাঙ্গর। শিকারী.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏مِنْ ‏ ‏بَنِي تَيْمٍ ‏ ‏يُقَالُ لَهُ ‏ ‏طَلْحَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏تَنَاوَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي صَائِمَةٌ فَقَالَ وَأَنَا صَائِمٌ ‏","","",""],[24129,24129,"","মা বলেছিলেন, ঈশ্বর তাঁর কাছে যা চেয়েছিলেন, তা হল প্রভু এবং তিনি এর জন্য যা করেছেন, সেই বিষয়টা । মহান জন্তুর অর্ধেক নিয়ে খেলা করে খুশি হলাম,","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ الْأَسَدِيِّ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْأَشْعَثِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْتَنِعُ مِنْ شَيْءٍ مِنْ وَجْهِي وَهُوَ صَائِمٌ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ ذَرِيحٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْأَشْعَثِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَهُ ‏","","",""],[24130,24130,"","আমরা কথা বলেছিলাম, তিনি কত কিছু অনুভব করেছিলেন, আপনি আমার কষ্টটা তার কাছে আর আত্মসমর্পণের জন্য মুছে ফেলেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ ‏ ‏تَغْسِلُ الْمَنِيَّ مِنْ ثَوْبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24131,24131,"","আমরা একটা বিয়ের কথা বলেছিলাম, যেখানে আমরা কথা বলেছি, সে ঈশ্বরের কাছে প্রার্থনা করতে হবে, যেন সে বাতাসে উদ্ধার করতে পারে এবং মুখে ধরা পড়ে যায়। আমরা যখন অবতরণ করলাম, তখন কর্নেল ডুবে গিয়েছিল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ يَوْمُ ‏ ‏عَاشُورَاءَ ‏ ‏يَوْمًا يَصُومُهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجَاهِلِيَّةِ وَكَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَصُومُهُ فِي الْجَاهِلِيَّةِ ‏ ‏فَلَمَّا قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏صَامَهُ وَأَمَرَ بِصِيَامِهِ فَلَمَّا نَزَلَ رَمَضَانُ كَانَ رَمَضَانُ هُوَ الْفَرِيضَةَ وَتَرَكَ ‏ ‏عَاشُورَاءَ ‏","","",""],[24132,24132,"","কয়েক মাস আগে আমার বাবা একটা মেয়ের সাথে যুদ্ধের কথা বলেছিলেন, যে এক মেয়ের সাথে যুদ্ধ করতে ভয় পেয়েছিল যে এক মেয়ে ছিল যে ছিল মহিলা, সে ছিল এক মহিলা যে মহিলা ছিল মহিলা। যে মহিলা মহিলা ছিলেন এক নারী নারী নারী, যে মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা। তিনি তার জন্য প্রার্থনা করেছিলেন এবং তার জন্য প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُصْعَبِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ ‏ ‏غَدَاةٍ ‏ ‏وَعَلَيْهِ ‏ ‏مِرْطٌ ‏ ‏مُرَجَّلٌ مِنْ شَعَرٍ أَسْوَدَ ‏","","",""],[24133,24133,"","আমরা তার খালাকে জীবন্ত রাখার জন্য কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَطْيَبَ مَا أَكَلْتُمْ مِنْ كَسْبِكُمْ وَإِنَّ أَوْلَادَكُمْ مِنْ كَسْبِكُمْ ‏","","",""],[24134,24134,"","আমরা যে - সময়ে কথা বলেছিলাম, সেই সময়ের মধ্যে আমরা সবচেয়ে ভাল কথা বলেছিলাম । ( গীতসংহিতা ৩৭: ১১) আপনি আমাকে এক নির্দিষ্ট উপায়ে ডেকে পাঠান । ঈশ্বরের সংকল্প আর তারপর প্রভু তার জন্য এমন করেছেন যে সে তার জন্য করেছে, যদি সে সম্মান চুরি করে, তুমি তাকে ছেড়ে দাও, যদি তারা চুরি করে, হাত কেটে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ امْرَأَةٌ مَخْزُومِيَّةٌ تَسْتَعِيرُ الْمَتَاعَ ‏ ‏وَتَجْحَدُهُ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَطْعِ يَدِهَا فَأَتَى أَهْلُهَا ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَكَلَّمُوهُ فَكَلَّمَ ‏ ‏أُسَامَةُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أُسَامَةُ ‏ ‏لَا أَرَاكَ تُكَلِّمُنِي فِي حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ ثُمَّ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطِيبًا فَقَالَ ‏ ‏إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِأَنَّهُ إِذَا سَرَقَ فِيهِمْ الشَّرِيفُ تَرَكُوهُ وَإِذَا سَرَقَ فِيهِمْ الضَّعِيفُ قَطَعُوهُ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ كَانَتْ ‏ ‏فَاطِمَةُ بِنْتُ مُحَمَّدٍ ‏ ‏لَقَطَعْتُ يَدَهَا فَقَطَعَ يَدَ الْمَخْزُومِيَّةِ ‏","","",""],[24135,24135,"","আমরা যে সমস্ত দলের সাথে আমাদের বিয়ে হওয়ার কথা বলেছিলাম তাদের মধ্যে থেকে আমরা কথা বলেছি। ঈশ্বরের অনুভূতি এমন একজন যে খুব সহজে খুঁজে পেয়েছে, সে এমন একজন মানুষ যে খুব সহজ ছিল। গ্রীষ্ম এবং বিশ্বের মহিমার সাথে পরম শান্তি। ঈশ্বর জয়ী হয়েছেন এবং তাঁর জন্য ঈশ্বরের প্রতি প্রেম করেছেন অথবা তাঁর জন্য করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ شَعَائِرِ اللَّهِ ‏} ‏قَالَتْ كَانَ رِجَالٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏مِمَّنْ ‏ ‏يُهِلُّ ‏ ‏لِمَنَاةَ فِي الْجَاهِلِيَّةِ وَمَنَاةُ صَنَمٌ بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏قَالُوا يَا نَبِيَّ اللَّهِ إِنَّا كُنَّا نَطُوفُ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏تَعْظِيمًا لِمَنَاةَ فَهَلْ عَلَيْنَا مِنْ حَرَجٍ أَنْ نَطُوفَ بِهِمَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ شَعَائِرِ اللَّهِ فَمَنْ حَجَّ ‏ ‏الْبَيْتَ ‏ ‏أَوْ اعْتَمَرَ ‏ ‏فَلَا جُنَاحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِمَا ‏}","","",""],[24136,24136,"","আপনি যে - আদেশ দেন, তা আমি কখনোই চেষ্টা করিনি । আমার প্রভু এটা শিখেছেন । যে ই এই জন ্ য একমাত্র সেই-ই বা কে সেই সেই যার কথা তিনি জীবিত আর কে সেই সেই ব্যক্তি যিনি তালিকার আর এই যে-ই তিনিই হলেন ? তিনিই হলেন সেই ব্যক্তি যিনি তাকে গোলাপ দিয়ে আর অন্য ডাক্তার পাঠান।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏إِنْ كُنْتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ ‏} ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ بِي فَقَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلَا عَلَيْكِ أَنْ لَا تَعْجَلِي فِيهِ حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ قَالَتْ قَدْ عَلِمَ وَاللَّهِ لَمْ يَكُونَا لِيَأْمُرَانِي بِفِرَاقِهِ قَالَتْ فَقَرَأَ عَلَيَّ ‏ { ‏يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا ‏} ‏فَقُلْتُ أَفِي هَذَا أَسْتَأْمِرُ أَبَوَيَّ فَإِنِّي أُرِيدُ اللَّهَ عَزَّ وَجَلَّ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ ‏","","",""],[24137,24137,"","আপনি যদি বিশ্বাস করেন, তাহলে ঈশ্বর আশীর্বাদ করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْتَحِنُ الْمُؤْمِنَاتِ إِلَّا بِالْآيَةِ الَّتِي قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِذَا جَاءَكَ الْمُؤْمِنَاتُ يُبَايِعْنَكَ عَلَى أَنْ لَا يُشْرِكْنَ ‏} ‏وَلَا وَلَا ‏","","",""],[24138,24138,"","বিয়ের কথা বলেছিলাম যে বিয়ের কথা বলার সময় সে আমাকে বলেছিল আমাকে খুন করার চেষ্টা করছে, তারা আমাকে ঢুকতে দেবে। আমি এটা নিয়ে নেব। মাসখানেক ধরে তুমি এটা গাইতে পার, আমি এটা গাইতে চাই এবং পরে পড়তে চাই। আমার বাবা সেখানে যেতে নিষেধ করেন নি। আমি চাই ঈশ্বর ও তার বার্তাবাহক। অন্য একটা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَأَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏فَلَمَّا مَضَتْ تِسْعٌ وَعِشْرُونَ لَيْلَةً دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ بَدَأَ بِي فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّكَ أَقْسَمْتَ أَنْ لَا تَدْخُلَ عَلَيْنَا شَهْرًا وَإِنَّكَ قَدْ دَخَلْتَ مِنْ تِسْعٍ وَعِشْرِينَ أَعُدُّهُنَّ فَقَالَ إِنَّ الشَّهْرَ تِسْعٌ وَعِشْرُونَ ثُمَّ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنِّي ذَاكِرٌ لَكِ أَمْرًا فَلَا عَلَيْكِ أَنْ لَا تَعْجَلِي فِيهِ حَتَّى تَسْتَأْمِرِي أَبَوَيْكِ ثُمَّ قَرَأَ عَلَيَّ الْآيَةَ ‏ { ‏يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ ‏ ‏حَتَّى بَلَغَ ‏ ‏أَجْرًا عَظِيمًا ‏} ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَدْ عَلِمَ أَنَّ أَبَوَيَّ لَمْ يَكُونَا يَأْمُرَانِي بِفِرَاقِهِ قَالَتْ فَقُلْتُ أَفِي هَذَا أَسْتَأْمِرُ أَبَوَيَّ فَإِنِّي أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ ‏","","",""],[24139,24139,"","আমি এমন একজন পর্যটকের জন্য যুদ্ধ করতে পারার ব্যাপারে সবচেয়ে ভালো কথা বলেছি, যিনি ভয় পেয়ে ফিরে আসবেন। আমি বলছি ঈশ্বরের বার্তাবাহকের সৃষ্টির কথা, আল্লাহ আছে। তার জন্য প্রার্থনা করলাম এবং বললো যে, সে তার জিনিয়াস।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ أَخْبِرِينِي عَنْ خُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏كَانَ خُلُقُهُ الْقُرْآنَ ‏","","",""],[24140,24140,"","আমরা কথা বলেছিলাম তার বাবা কিভাবে বেঁচে আছে সে সম্পর্কে আমাদের বলেছেন। ঈশ্বর জানেন কিভাবে একজন মানুষ হত্যা করে, সে বলে ঈশ্বর বরং বল, আমি তোমার হৃদয়ের সাথে পরিচিত হয়েছি, আমি তোমার হৃদয়ের কথা বলি, আমি তোমার হৃদয়ের সাথে পরিচিত হয়েছি, আমি যা করি তার চেয়ে ভাল বলতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ ‏ ‏كَيْفَ يَأْتِيكَ الْوَحْيُ يَا نَبِيَّ اللَّهِ قَالَ ‏ ‏يَأْتِينِي أَحْيَانًا لَهُ صَلْصَلَةٌ كَصَلْصَلَةِ الْجَرَسِ فَيَنْفَصِمُ عَنِّي وَقَدْ وَعَيْتُ وَذَلِكَ أَشَدُّهُ عَلَيَّ ‏ ‏وَيَأْتِينِي أَحْيَانًا فِي صُورَةِ الرَّجُلِ ‏ ‏أَوْ قَالَ الْمَلَكِ ‏ ‏فَيُخْبِرُنِي فَأَعِي مَا يَقُولُ ‏","","",""],[24141,24141,"","আমরা পৃথিবীর সর্বোত্তমতমতমতমের বিষয়ে কথা বলেছিলাম, সেই দিনই সেই ছেলে যে - দিন এসেছিল, সেই সম্বন্ধে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُقْطَعُ يَدُ السَّارِقِ فِي رُبُعِ دِينَارٍ فَصَاعِدًا ‏","","",""],[24142,24142,"","আমরা একটি ছোট ছেলের কথা বলেছিলাম যে তার বয়স সম্পর্কে আমাদের কিছু বলেছে, সে এমন কিছু মনে করে যা ঈশ্বরের জন্য ভালো ছিল আর সে তার ছেলেকে মৃত্যুর দিকে নিয়ে যাবে। আমি ভবিষ্যদ্বাণী করে আসছিলাম যে, মূল্য মূল্যের মূল্য দেওয়ার আগে তিনি সবচেয়ে বেশি চিন্তিত হয়ে পড়েছিলেন । দামের দামের দামের জন্য আমরা বলেছিলাম, শহীদের ছেলে তার বয়স সম্পর্কে বলা এক ছেলেকে বলেছিলাম। প্রথমে দাম দিতে বলা হয়.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏أُخْبِرْتُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ وَهِيَ تَذْكُرُ شَأْنَ ‏ ‏خَيْبَرَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُ ‏ ‏ابْنَ رَوَاحَةَ ‏ ‏إِلَى ‏ ‏الْيَهُودِ ‏ ‏فَيَخْرُصُ ‏ ‏عَلَيْهِمْ النَّخْلَ حِينَ يَطِيبُ قَبْلَ أَنْ يُؤْكَلَ مِنْهُ ثُمَّ يُخَيِّرُونَ ‏ ‏يَهُودَ ‏ ‏أَيَأْخُذُونَهُ بِذَلِكَ ‏ ‏الْخَرْصِ ‏ ‏أَمْ يَدْفَعُونَهُ إِلَيْهِمْ بِذَلِكَ وَإِنَّمَا كَانَ أَمْرُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْخَرْصِ لِكَيْ يُحْصِيَ الزَّكَاةَ قَبْلَ أَنْ تُؤْكَلَ الثَّمَرَةُ وَيُفَرَّقَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ ‏ ‏بَلَغَهُ ‏ ‏عَنْهُ عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ وَهِيَ تَذْكُرُ شَأْنَ ‏ ‏خَيْبَرَ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ حِينَ يَطِيبُ أَوَّلُ التَّمْرِ وَقَالَ قَبْلَ أَنْ تُؤْكَلَ الثِّمَارُ ‏","","",""],[24143,24143,"","আমরা একজন যাজকের সাথে বিয়ে নিয়ে কথা বলেছি, যে কিনা তার বসের সাথে যৌন সম্পর্ক করেছে, আর আমি তাকে আর শার্কবি যুক্তির সার্ফকে আত্মসমর্পণ করব একবার যখন সে বলেছিল যে সে কাকে স্বপ্ন দেখছে আমি জানতাম একবার যদি আমি সাহস করি, আমার বাবা আমার ইচ্ছা দিয়ে পার হয়ে যাবে কিনা, আমি তার কথা ভুলেই গিয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ حَجَّةِ الْوَدَاعِ ‏ ‏فَأَهْلَلْتُ ‏ ‏بِعُمْرَةٍ وَلَمْ أَكُنْ سُقْتُ الْهَدْيَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مَعَهُ الْهَدْيُ ‏ ‏فَلْيُهِلَّ ‏ ‏بِالْحَجِّ مَعَ عُمْرَتِهِ ‏ ‏ثُمَّ لَا يَحِلَّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا فَحِضْتُ فَلَمَّا دَخَلَتْ لَيْلَةُ ‏ ‏عَرَفَةَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي كُنْتُ ‏ ‏أَهْلَلْتُ ‏ ‏بِعُمْرَةٍ فَكَيْفَ أَصْنَعُ بِحَجَّتِي قَالَ ‏ ‏انْقُضِي ‏ ‏رَأْسَكِ وَامْتَشِطِي وَأَمْسِكِي عَنْ الْعُمْرَةِ ‏ ‏وَأَهِلِّي ‏ ‏بِالْحَجِّ فَلَمَّا قَضَيْتُ حَجَّتِي أَمْرَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرٍ ‏ ‏فَأَعْمَرَنِي مِنْ ‏ ‏التَّنْعِيمِ ‏ ‏مَكَانَ عُمْرَتِي الَّتِي نَسَكْتُ عَنْهَا ‏","","",""],[24144,24144,"","তিনি ভাববাদীকে বলেছিলেন, তার কাছে প্রার্থনা করুন এবং মাখনের মাংসের ঝোঁকে দিয়ে মাখনের টুকরো বের করে দিয়েছিলেন । সিংহাসন, বারবারের হত্যা তার কাছে প্রার্থনা করা হয়েছে আর আমার ধাঁধাকে আমার প্রেমিকদের কাছে পেশ করা হবে যে আমি আমার ভালবাসার জন্য চেষ্টা করছি না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏ضُبَاعَةَ بِنْتِ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏فَقَالَتْ إِنِّي أُرِيدُ الْحَجَّ وَأَنَا شَاكِيَةٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجِّي وَاشْتَرِطِي أَنَّ مَحِلِّي حَيْثُ ‏ ‏حَبَسْتَنِي ‏","","",""],[24145,24145,"","আমরা পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি, সে আমাকে শুধু বলে যে, এক প্রাক্তন গ্রীষ্মের কথা আমরা তাকে পছন্দ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ أَرَادَ أَنْ يَنْفِرَ ‏ ‏أُخْبِرَ أَنَّ ‏ ‏صَفِيَّةَ ‏ ‏حَائِضٌ فَقَالَ ‏ ‏أَحَابِسَتُنَا ‏ ‏هِيَ فَأُخْبِرَ أَنَّهَا قَدْ أَفَاضَتْ فَأَمَرَهَا بِالْخُرُوجِ ‏","","",""],[24146,24146,"","ঈশ্বর যুদ্ধ এবং সূর্যের মধ্যে পাঁচবার মারা যাওয়ার মাধ্যমে আমাদের উদ্ধার করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ خَمْسِ فَوَاسِقَ فِي الْحِلِّ وَالْحَرَمِ الْحِدَأَةِ وَالْعَقْرَبِ وَالْفَأْرَةِ وَالْغُرَابِ وَالْكَلْبِ ‏ ‏الْعَقُورِ ‏","","",""],[24147,24147,"","আমরা আমার ভাইয়ের ছেলে, একজন কাজিনের ছেলে, যে আমাকে বিয়ের ছেলেকে বিয়ে করতে বলেছিল, তার জন্য প্রার্থনা করেছিল। ঈশ্বর তার জন্য প্রার্থনা করবে এবং তিনি তাকে আদেশ দিয়েছেন, তিনি তাকে পাঁচ জন বলেছে। আর কুকুরের যুদ্ধ হল হল হল হল হলের কাছে আর মেঘই হল একমাত্র উপায়।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ مِنْ الدَّوَابِّ كُلُّهُنَّ فَاسِقٌ يُقْتَلْنَ فِي الْحِلِّ وَالْحَرَمِ الْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْعَقْرَبُ وَالْغُرَابُ وَالْحِدَأَةُ وَالْفَأْرَةُ ‏","","",""],[24148,24148,"","আমরা একটা ছেলের কথা বলেছিলাম, তার বাবার জীবন নিয়ে আমরা কথা বলেছিলাম, যা সূর্যকে তার প্রচেষ্টায় হারিয়ে ফেলেছিল। মূল্যবোধের অনেক কিছু তিনি প্রথমে শপথটি খুঁজে বের করার জন্য প্রথম এবং তিনি প্রথম হাঁটু প্রথম ধাপ, তারপর রিং শেষ হয়. প্রথম স্তম্ভটি লর্ড লর্ড্স-এর জন্য ব্যয় করা হয় লর্ডশীপের শান্তি, সংরক্ষিত করা হয়েছে, সে এটা ঈশ্বরের অনুগ্রহ থেকে করেছে এবং তারপর তার হৃদয়ের ক্ষতি করেনি, তারা ঈশ্বরকে ডাকে এবং তারা বিশ্বাস করে, না, না, না, না, না, না, না, না, না, না, না, না, না, না, না, না, না, না, তুমি আমাকে তার মা, যোগ্য জাতি, ঈশ্বর জয় কর, যদি তুমি জানো যে তোমার বাবার জন্য আমি কি করি।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَسَفَتْ الشَّمْسُ فِي عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَأَطَالَ الْقِيَامَ جِدًّا ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ جِدًّا ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ فَأَطَالَ الْقِيَامَ جِدًّا وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ سَجَدَ ثُمَّ قَامَ فَأَطَالَ الْقِيَامَ وَهُوَ دُونَ الْأَوَّلِ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ فَأَطَالَ الْقِيَامَ وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ وَهُوَ دُونَ الرُّكُوعِ الْأَوَّلِ ثُمَّ سَجَدَ فَانْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ ‏ ‏تَجَلَّتْ ‏ ‏الشَّمْسُ فَخَطَبَ النَّاسَ فَحَمِدَ اللَّهَ عَزَّ وَجَلَّ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ مِنْ آيَاتِ اللَّهِ وَإِنَّهُمَا لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ فَإِذَا رَأَيْتُمُوهُمَا فَكَبِّرُوا وَادْعُوا اللَّهَ عَزَّ وَجَلَّ وَصَلُّوا وَتَصَدَّقُوا يَا أُمَّةَ ‏ ‏مُحَمَّدٍ ‏ ‏مَا مِنْ أَحَدٍ أَغْيَرُ مِنْ اللَّهِ عَزَّ وَجَلَّ أَنْ يَزْنِيَ عَبْدُهُ أَوْ تَزْنِيَ أَمَتُهُ يَا أُمَّةَ ‏ ‏مُحَمَّدٍ ‏ ‏وَاللَّهِ لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَكَيْتُمْ كَثِيرًا وَلَضَحِكْتُمْ قَلِيلًا أَلَا هَلْ بَلَّغْتُ ‏","","",""],[24149,24149,"","আমরা একটা জীবন্ত প্রবাদের বিষয়ে বলেছিলাম, যে তিনি শপথের বিষয়ে শুনেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَرَى ‏ ‏صَفِيَّةَ ‏ ‏إِلَّا ‏ ‏حَابِسَتُنَا ‏ ‏قَالَ أَوَلَمْ تَكُنْ ‏ ‏أَفَاضَتْ ‏ ‏قَالَتْ بَلَى قَالَ فَلَا ‏ ‏حَبْسَ ‏ ‏عَلَيْكِ ‏ ‏فَنَفَرَ ‏ ‏بِهَا ‏","","",""],[24150,24150,"","আমরা এমন এক ছেলের কথা বলেছিলাম যে ঈশ্বরের জীবন নিয়ে কথা বলেছিল, আমাকে ঈশ্বরের দোহাই দিতে হবে, তাকে এটা উদ্ধার করতে হবে এবং তিনি তা প্রদান করবেন, একবার তিনি তা উদ্ধার করবেন, যখন মানুষ আসার আগে। ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তাকে আত্মসমর্পণ করতে হয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَوَدِدْتُ أَنِّي كُنْتُ ‏ ‏اسْتَأْذَنْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمَا اسْتَأْذَنَتْهُ ‏ ‏سَوْدَةُ ‏ ‏فَأُصَلِّي الصُّبْحَ ‏ ‏بِمِنًى ‏ ‏وَأَرْمِي الْجَمْرَةَ مِنْ قَبْلِ أَنْ يَأْتِيَ النَّاسُ فَقِيلَ لَهَا وَكَانَتْ اسْتَأْذَنَتْهُ قَالَتْ نَعَمْ إِنَّهَا كَانَتْ امْرَأَةً ثَقِيلَةً ‏ ‏ثَبِطَةً ‏ ‏فَاسْتَأْذَنَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَذِنَ لَهَا ‏","","",""],[24151,24151,"","আমরা একটা ছেলের কথা বলেছিলাম, যিনি ভণ্ডারদের কথা বলেছিলেন । সে-ই ব ্ যতীত যে ব ্ যক ্ তি এই পৃথিবীতে থাকবে এবং সে-ই হবে বিজয়ী । সেই ব্যক্তি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি রাজা হবেন ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ‏ ‏الرَّكْعَتَيْنِ اللَّتَيْنِ قَبْلَ الْفَجْرِ فَيُخَفِّفُهُمَا حَتَّى أَقُولَ هَلْ قَرَأَ فِيهِمَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏","","",""],[24152,24152,"","আমরা একটা জীবন নিয়ে কথা বলেছি যে আমরা ঈশ্বর প্রদত্ত তার অনুগ্রহের কথা বলছি, আমি তোমাদের সবাইকে এক সময় যেতে দেব এবং ফিরে আসবো আমি তার সাথে না। গরমের মধ্যে পড়ে যায় আর ছোটগুলো গরু হয়ে যায় ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَرْجِعُ نِسَاؤُكَ بِحَجَّةٍ وَعُمْرَةٍ وَأَرْجِعُ أَنَا بِحَجَّةٍ لَيْسَ مَعَهَا عُمْرَةٌ فَأَقَامَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَالْبَطْحَاءِ ‏ ‏وَأَمَرَهَا فَخَرَجَتْ إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏وَخَرَجَ مَعَهَا أَخُوهَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏فَأَحْرَمَتْ بِعُمْرَةٍ ثُمَّ أَتَتْ ‏ ‏الْبَيْتَ ‏ ‏فَطَافَتْ بِهِ وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَقَصَّرَتْ فَذَبَحَ عَنْهَا بَقَرَةً ‏","","",""],[24153,24153,"","আমরা একটা ছেলের কথা বলেছিলাম যে ছেলেটির শপথ নিয়ে খুশি হতে পেরে আমি খুশি। সে বলবে আমি ঈশ্বরের দোহাইর জন্য টাকা দিতে পছন্দ করি আর তাকে দোষারোপ করি","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعْدُ بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ عَزَّ وَجَلَّ أَدْوَمُهَا وَإِنْ قَلَّ ‏","","",""],[24154,24154,"","কীভাবে ঈশ্বরের বাক্য তার কাছে প্রার্থনা করেছিল এবং বলেছিলেন যে, তিনি যদি হতেন, তা হলে তিনি নিশ্চয়ই তা করতেন । আমি দেখেছি যে, এটা তার নিজের মহাবিশ্বের চেয়ে দ্রুততমতমতমতমতমতমতমতম।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ أَيْ ‏ ‏أُمَّهْ كَيْفَ كَانَ صِيَامُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ ‏ ‏يَصُومُ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ وَلَمْ أَرَهُ يَصُومُ مِنْ شَهْرٍ أَكْثَرَ مِنْ صِيَامِهِ مِنْ شَعْبَانَ كَانَ يَصُومُ شَعْبَانَ إِلَّا قَلِيلًا بَلْ كَانَ يَصُومُهُ كُلَّهُ ‏","","",""],[24155,24155,"","\"আমি শুনেছি, ঈশ্বরের অনুগ্রহ তার কাছে এসেছে এবং আপনার জীবন প্রার্থনা করছে\" এবং আমি একটি ভাল শ্রেণী সম্পর্কে শুনেছি। \"আমি শুনেছি, \"আমি শুনেছি, ঈশ্বরের অনুগ্রহ তার কাছে এসেছে\"। আমার বিস্ফোরণ তোমাকে তিনবার হত্যা করেছে.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَرَوْحٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ اللَّيْلِ عَشْرَ رَكَعَاتٍ يُوتِرُ بِسَجْدَةٍ وَيَرْكَعُ رَكْعَتَيْ الْفَجْرِ فَتِلْكَ ثَلَاثَ عَشْرَةَ ‏","","",""],[24156,24156,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমরা একটা ছেলের সাথে দেখা করেছি যে তোমাকে খুন করবে, জীবিত থাকবে, প্রভু, যদি সে গৌরবের অধিকারী হয়, ঈশ্বর তার কাছে প্রার্থনা করে এবং সে আছে আমার মা ও আমি আপনাদের মতো আমার মায়ের প্রতি উদ্যোগ গড়ে তুলেছে ।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنِ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَبْطَأْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا حَبَسَكِ يَا ‏ ‏عَائِشَةُ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ فِي الْمَسْجِدِ رَجُلًا مَا رَأَيْتُ أَحَدًا أَحْسَنَ قِرَاءَةً مِنْهُ قَالَ فَذَهَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ ‏ ‏سَالِمٌ مَوْلَى أَبِي حُذَيْفَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي أُمَّتِي مِثْلَكَ ‏","","",""],[24157,24157,"","ঈশ্বর তাকে দাবি করেছেন এবং তাঁর সাধারণ পরিচিতিকে সমর্পণ করেছেন এবং আপনি যা করতে পারতেন, সেগুলোর জন্য তিনি আকুল আকাঙ্ক্ষী ছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ يَمِينُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِطَعَامِهِ وَصَلَاتِهِ وَكَانَتْ شِمَالُهُ لِمَا سِوَى ذَلِكَ ‏","","",""],[24158,24158,"","আমরা এক দশক ধরে একটি মেয়ের ক্ষেপন নিয়ে কথা বলেছি। ঈশ্বরের ভিক্ষুকরা চেষ্টার মধ্যে আছে, আমরা জানতাম যে তারা লড়াই করবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ابْنَةِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ هَلْ عَلَى النِّسَاءِ مِنْ جِهَادٍ قَالَ نَعَمْ ‏ ‏عَلَيْهِنَّ جِهَادٌ لَا قِتَالَ فِيهِ الْحَجُّ وَالْعُمْرَةُ ‏","","",""],[24159,24159,"","তিনি তিনটে জাদুর উপজাতির হাতে নিযুক্ত হয়েছেন, যেগুলো একটা শার্টের মধ্যে নেই, যা জগতের সাধারণ জ্ঞান নয় ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُفِّنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَلَاثَةِ أَثْوَابٍ ‏ ‏سُحُولِيَّةٍ ‏ ‏لَيْسَ فِيهَا قَمِيصٌ وَلَا عِمَامَةٌ ‏","","",""],[24160,24160,"","আমি একটা জীবন্ত কথা শুনেছি, যেখানে আমি ঈশ্বরের কাছে প্রার্থনা করব আমি তার জন্য আর প্রতিবেশীদের কাছে প্রার্থনা করব। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ইচ্ছার জন্য প্রার্থনা করেছেন। ঈশ্বর আপনার কাছে আসবে এবং যদি তিনি চান ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي مُلَيْكَةَ ‏ ‏قَالَ قَالَ ‏ ‏ذَكْوَانُ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَارِيَةِ ‏ ‏يُنْكِحُهَا أَهْلُهَا أَتُسْتَأْمَرُ أَمْ لَا فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُسْتَأْمَرُ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ لَهُ فَإِنَّهَا تَسْتَحِي فَتَسْكُتُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَلِكَ إِذْنُهَا إِذَا هِيَ سَكَتَتْ ‏","","",""],[24161,24161,"","আমরা এক দশক ধরে বাবার মৃত্যুর কথা বলেছি, আমরা ভাববাদীকে তার জন্য প্রার্থনা করছি এবং তাকে হত্যা করার প্রচেষ্টায় আত্মসমর্পণ করছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتِ ‏ ‏اسْتَأْذَنَّا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجِهَادِ فَقَالَ ‏ ‏حَسْبُكُنَّ الْحَجُّ ‏ ‏أَوْ جِهَادُكُنَّ الْحَجُّ ‏","","",""],[24162,24162,"","আমরা পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি। আমি তাকে বললাম যে, সে তাকে বলেছে যে ভবিষ্যদ্বাণী তার জন্য প্রার্থনা করেছে এবং সে যা কিছু করে তার জন্য সে ছেড়ে দেবে। ডানা, তার দক্ষতা আছে, আর সে তার থেকে পালিয়ে আসছে, আর সে খুব কম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عُرْوَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا امْرَأَةٍ ‏ ‏أُنْكِحَتْ ‏ ‏بِغَيْرِ إِذْنِ ‏ ‏مَوَالِيهَا ‏ ‏فَنِكَاحُهَا بَاطِلٌ ثَلَاثًا وَلَهَا مَهْرُهَا بِمَا أَصَابَ مِنْهَا فَإِنْ اشْتَجَرُوا فَإِنَّ السُّلْطَانَ ‏ ‏وَلِيُّ ‏ ‏مَنْ لَا ‏ ‏وَلِيَّ ‏ ‏لَهُ ‏","","",""],[24163,24163,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং সূর্যের অনুগ্রহের আগে আমাকে তাড়াতাড়ি যেতে দেওয়ার জন্য কিছু একটা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى شَيْءٍ أَسْرَعَ مِنْهُ إِلَى رَكْعَتَيْنِ قَبْلَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏وَلَا إِلَى غَنِيمَةٍ يَطْلُبُهَا ‏","","",""],[24164,24164,"","আমরা দশ বছর ধরে জীবন যাপনের কথা বলেছিলাম, সে বলেছিল আমি ভাববাদীকে অনুরোধ করব তাকে নিয়ে যাজকের কাছে আত্মসমর্পণ করব... তাই নাকি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ بِنْتِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْجِهَادِ فَقَالَ ‏ ‏بِحَسْبِكُنَّ ‏ ‏الْحَجُّ ‏ ‏أَوْ قَالَ جِهَادُكُنَّ الْحَجُّ ‏","","",""],[24165,24165,"","আমার জীবনের এই ভবিষ্যদ্বাণী ছিল তার জন্য প্রার্থনা করা এবং আমার প্রার্থনা অনেক লম্বা সময় ধরে আমি তা করে আসছি । তিনি তার সঙ্গে যে - বার্তা বলেছিলেন, তা শুনে তিনি কী বলেছিলেন?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ السَّخْتِيَانِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا وَلَيْلًا طَوِيلًا قَاعِدًا قَالَ قُلْتُ كَيْفَ كَانَ يَصْنَعُ قَالَتْ كَانَ إِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[24166,24166,"","আমরা আমার আত্মাকে এমন একটা ছেলের সাথে বাস করার কথা বলেছিলাম যে নিজেকে মেরে ফেলতে চায়। ঈশ্বরের অনুগ্রহ তাকে উদ্ধার করা হয়েছে এবং সে ঘুমিয়ে আছে, আর সম্ভবত তাকে আমাকে হত্যা করতে বলা হয়েছে। কিন্তু এক ঘন্টার মধ্যে ঋণ শোধ করার উদ্যোগ বলতে সে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ وَهُوَ جُنُبٌ قَالَتْ لِي ‏ ‏رُبَّمَا ‏ ‏اغْتَسَلَ قَبْلَ أَنْ يَنَامَ وَرُبَّمَا نَامَ قَبْلَ أَنْ يَغْتَسِلَ وَلَكِنَّهُ كَانَ يَتَوَضَّأُ قَالَ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الدِّينِ سَعَةً ‏","","",""],[24167,24167,"","আমরা মাখনের সাথে নগ্ন হয়ে কথা বলেছিলাম যে চুলার হয়তো চলে যাবে, খোদা আমার বাবার বড় হাতের কাজ আর তার বইয়েও ছিল... ...তাই সে আমার বিয়ে ঈশ্বরের ছেলে হওয়ার কথা বলছিল. একজন মহিলা এসে তার দুই মেয়ে ছিল আর তার কোন ধারণাই ছিল না তার কোন সমস্যা ছিল। আমার মেয়ে তাকে কিছু খায় নি, তারপর সে বাইরে বের হয়ে যায়। আমি তার সাথে কথা বলেছি। আমি তার সাথে এবং তার সাথে কথা বলেছি। আমি তাকে বলেছিলাম, আমার মেয়ে কোন ভুল ধারণাই করেনি যে তার কোন ভুল ছিল। আমার মেয়ে তাকে কিছু খেতে বলেছে। আমার মেয়ে কিছু একটা করে নি। আমি তাকে বলেছিলাম, আমি তাকে ছেড়ে চলে যেতে বলেছি। আমি তাকে বলেছিলাম। আর সে যেন তার সাথে বাইরে গিয়ে দেখি যে কেউ কোন কথা বলে। কিন্তু আমি তাকে জিজ্ঞেস করি, আমি জানি না যে, আমি তাকে নিয়ে যাই। আমি জানি না যে, আমি তাকে নিয়ে বাইরে যেতে চাই। আমি জানি না। আমি কি বলছি, আমি জানি না। আমি জানি যে, আমি জানি, আমি জানি না যে, আমি তাকে বলছি, আমি জানি না। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন, যে কিনা এই ছেলেটির কাছে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَكَانَ يَذْكُرُهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏وَكَذَا كَانَ فِي كِتَابهِ ‏ ‏يَعْنِي ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ امْرَأَةٌ وَمَعَهَا ابْنَتَانِ لَهَا فَلَمْ تَجِدْ عِنْدِي شَيْئًا غَيْرَ تَمْرَةٍ وَاحِدَةٍ فَأَعْطَيْتُهَا إِيَّاهَا فَأَخَذَتْهَا فَشَقَّتْهَا بَيْنَ ابْنَتَيْهَا وَلَمْ تَأْكُلْ مِنْهَا شَيْئًا ثُمَّ قَامَتْ فَخَرَجَتْ هِيَ وَابْنَتَاهَا فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏تَفِيئَةِ ‏ ‏ذَلِكَ فَحَدَّثْتُهُ حَدِيثَهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ابْتُلِيَ مِنْ هَذِهِ الْبَنَاتِ بِشَيْءٍ فَأَحْسَنَ إِلَيْهِنَّ كُنَّ سِتْرًا لَهُ مِنْ النَّارِ ‏","","",""],[24168,24168,"","আমরা বিয়ের ব্যাপারে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর লর্ডকে আমার ভালোবাসার ভালোবাসা ফিরিয়ে দিতে বলেছেন। আমি তার ফোন দেখে খুশি হব এবং তারপর তাকে দেখতে পাবো। আমার কান থেকে তাদেরকে খেলা শুরু করে তারপর তার সবচেয়ে ভালো বন্ধু হওয়া। একমাত্র প্রতিবেশী যে পবিত্র ভুতের মুক্ত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَاللَّهِ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ عَلَى بَابِ حُجْرَتِي ‏ ‏وَالْحَبَشَةُ ‏ ‏يَلْعَبُونَ بِالْحِرَابِ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتُرُنِي بِرِدَائِهِ لِأَنْظُرَ إِلَى لَعِبِهِمْ مِنْ بَيْنِ أُذُنِهِ وَعَاتِقِهِ ثُمَّ يَقُومُ مِنْ أَجْلِي حَتَّى أَكُونَ أَنَا الَّتِي أَنْصَرِفُ فَاقْدُرُوا قَدْرَ ‏ ‏الْجَارِيَةِ ‏ ‏الْحَدِيثَةِ السِّنِّ الْحَرِيصَةِ عَلَى اللَّهْوِ ‏","","",""],[24169,24169,"","আমরা সময়ের সাথে কথা বলেছি... ...যা আমাদের সবার জীবনে অভিজ্ঞতার অভিজ্ঞতা হয়েছে। যদি আমি আমার বন্ধু হই, তাহলে সে প্রভুর অনুগ্রহে, তার নিজের মুক্তি আছে। আমাকে পৌঁছে দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَلْعَبُ بِاللُّعَبِ فَيَأْتِينِي صَوَاحِبِي ‏ ‏فَإِذَا دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَرْنَ مِنْهُ فَيَأْخُذُهُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَرُدُّهُنَّ إِلَيَّ ‏","","",""],[24170,24170,"","ঈশ্বর যে - রোগীর সঙ্গে কথা বলেছেন, তাদের মধ্যে তিনি ইতিমধ্যেই যে - রোগীর সঙ্গে আছেন, তাদের জন্য তিনি শ্বাস নিয়ে আসবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْفُثُ عَلَى نَفْسِهِ فِي الْمَرَضِ الَّذِي قُبِضَ فِيهِ مِنْهُ بِالْمُعَوِّذَاتِ ‏","","",""],[24171,24171,"","আমরা আমাদের সবার থেকে ভালো কথা বলেছি লর্ডের কসম কথা বলতে, তাকে প্রভুর নাম এখানে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا رَأَى ‏ ‏الْغَيْثَ ‏ ‏قَالَ اللَّهُمَّ ‏ ‏صَيِّبًا ‏ ‏هَنِيئًا ‏","","",""],[24172,24172,"","তিনি আমাকে বলেছিলেন যে, তিনি কে, যিনি বলেন, আমি একজন পাঠকের কথা শুনছিলাম । ( খ) কীভাবে আমরা ঈশ্বরের মঙ্গলভাবের প্রতি উপলব্ধি দেখাতে পারি?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏نِمْتُ فَرَأَيْتُنِي فِي الْجَنَّةِ فَسَمِعْتُ صَوْتَ قَارِئٍ يَقْرَأُ فَقُلْتُ مَنْ هَذَا فَقَالُوا هَذَا ‏ ‏حَارِثَةُ بْنُ النُّعْمَانِ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَلِكَ ‏ ‏الْبِرُّ ‏ ‏كَذَلِكَ ‏ ‏الْبِرُّ ‏ ‏وَكَانَ ‏ ‏أَبَرَّ ‏ ‏النَّاسِ ‏ ‏بِأُمِّهِ ‏","","",""],[24173,24173,"","আমরা বিয়ের ব্যাপারে কথা বলেছিলাম, বিখ্যাত ব্যাক্তিকে বলেছিলাম যে খোদাকে নার্স হতে হবে নাকি ভালো বোধ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مَرَضٍ أَوْ وَجَعٍ يُصِيبُ الْمُؤْمِنَ إِلَّا كَانَ كَفَّارَةً لِذَنْبِهِ حَتَّى الشَّوْكَةِ يُشَاكُهَا أَوْ النَّكْبَةِ يُنْكَبُهَا ‏","","",""],[24174,24174,"","আমরা বিয়ের কথা বলেছিলাম বেনের খুশির কথা। তিনি বলেছেন, ফাদার ঈশ্বরের কাছে প্রার্থনা করবেন যেন তিনি কেবল তাঁর সাথে তার আশ্বস্ত হন। বৃষ্টিতে আমার সাথে সে বেরিয়ে গেল, তারপর সে চলে গেল আর তারপর সে বসে বসে তার টাকা চায়, তাহলে আমাকে জিজ্ঞেস করতে হবে যে তুমি ভুল করলে তাকে খুন করতে হবে, তার প্রয়োজন নেই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اسْتَأْذَنَ ‏ ‏أَبُو بَكْرٍ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ فِي ‏ ‏مِرْطٍ ‏ ‏وَاحِدٍ قَالَتْ فَأَذِنَ لَهُ فَقَضَى إِلَيْهِ حَاجَتَهُ وَهُوَ مَعِي فِي ‏ ‏الْمِرْطِ ‏ ‏ثُمَّ خَرَجَ ثُمَّ اسْتَأْذَنَ عَلَيْهِ ‏ ‏عُمَرُ ‏ ‏فَأَذِنَ لَهُ فَقَضَى إِلَيْهِ حَاجَتَهُ عَلَى تِلْكَ الْحَالِ ثُمَّ خَرَجَ ثُمَّ اسْتَأْذَنَ عَلَيْهِ ‏ ‏عُثْمَانُ ‏ ‏فَأَصْلَحَ عَلَيْهِ ثِيَابَهُ وَجَلَسَ فَقَضَى إِلَيْهِ حَاجَتَهُ ثُمَّ خَرَجَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ لَهُ يَا رَسُولَ اللَّهِ اسْتَأْذَنَ عَلَيْكَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَضَى إِلَيْكَ حَاجَتَهُ عَلَى حَالِكَ تِلْكَ ثُمَّ اسْتَأْذَنَ عَلَيْكَ ‏ ‏عُمَرُ ‏ ‏فَقَضَى إِلَيْكَ حَاجَتَهُ عَلَى حَالِكَ ثُمَّ اسْتَأْذَنَ عَلَيْكَ ‏ ‏عُثْمَانُ ‏ ‏فَكَأَنَّكَ احْتَفَظْتَ فَقَالَ ‏ ‏إِنَّ ‏ ‏عُثْمَانَ ‏ ‏رَجُلٌ حَيِيٌّ وَإِنِّي لَوْ أَذِنْتُ لَهُ عَلَى تِلْكَ الْحَالِ خَشِيتُ أَنْ لَا يَقْضِيَ إِلَيَّ حَاجَتَهُ ‏","","",""],[24175,24175,"","আমরা যে সময়ের কথা বলেছি, তা হল আল্লাহ আমার দোষ, আমার কাছে একটা খারাপ স্বাদ আছে আর আমি আমার অতিথি হওয়ার শপথ নিয়েছি। আর এটা মিথ্যা কথা যে, এটা একটা মিথ্যা কথা। আর এটা একটা মিথ্যা কথা। আর এটা হল, ঈশ্বর আমাদের কাছে যা বলেছেন, এটা আমার কাছে একটা মিথ্যা। আমি যদি বলি, আমি তা হলে আমি যা করেছি তা হবে তা হল, আমি জানি না কেন, আমি জানি না? ওর কাছে প্রার্থনা কর আর চিৎকার করে বলো যখন সে ফাঁস হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً جَاءَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي زَوْجًا وَلِي ضَرَّةً وَإِنِّي أَتَشَبَّعُ مِنْ زَوْجِي أَقُولُ أَعْطَانِي كَذَا وَكَسَانِي كَذَا وَهُوَ كَذِبٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ زُورٍ ‏","","",""],[24176,24176,"","আমরা সবার সেরা কথা বলেছি বিয়ের ব্যাপারে আমাদের কথা বলতে। একজন নরমানুষ ঈশ্বরের কাছে অনুরোধ করেছিল যেন সে এমন কিছু করে, যা সে করে। আর এটা নিজের বাড়িতে করে নিজের ইউনিটে করে দাও.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏وَعَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْمَلُ فِي بَيْتِهِ شَيْئًا قَالَتْ نَعَمْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْصِفُ نَعْلَهُ وَيَخِيطُ ثَوْبَهُ وَيَعْمَلُ فِي بَيْتِهِ كَمَا يَعْمَلُ أَحَدُكُمْ فِي بَيْتِهِ ‏","","",""],[24177,24177,"","আমরা আমাদের জীবনের সর্বোত্তমটা নিয়ে কথা বলেছি, একজন বাবা যে - কাজ করেছেন, সেই বিষয়ে আমাদের একটা পরিবারের ছেলেকে বলেছিলাম, ঈশ্বর আত্মসমর্পণ করতে হবে যদি সে তার চেহারা পরিবর্তন করতে এবং তার চেহারা পরিবর্তন করতে চায়। আমি কখনোই ঈশ্বর যেমন তাকে বলেছিলেন, যেন তিনি কাঠবিড়ালী হিসেবে দেখেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى ‏ ‏مَخِيلَةً ‏ ‏تَغَيَّرَ وَجْهُهُ وَدَخَلَ وَخَرَجَ وَأَقْبَلَ وَأَدْبَرَ فَإِذَا ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَذُكِرَ ذَلِكَ لَهُ فَقَالَ ‏ ‏مَا أَمِنْتُ أَنْ يَكُونَ كَمَا قَالَ اللَّهُ ‏ { ‏فَلَمَّا رَأَوْهُ ‏ ‏عَارِضًا ‏ ‏مُسْتَقْبِلَ أَوْدِيَتِهِمْ ‏ ‏إِلَى ‏ ‏رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ ‏}","","",""],[24178,24178,"","আমরা পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি, সে আমার বাবার পোশাকের কথা শুনে এবং সে আমাকে বলেছে যে, সে আমার বাবা অথবা বাবাকে নিয়ে যেতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ صَوْتَ ‏ ‏أَبِي مُوسَى الْأَشْعَرِيِّ ‏ ‏وَهُوَ يَقْرَأُ فَقَالَ ‏ ‏لَقَدْ أُوتِيَ ‏ ‏أَبُو مُوسَى ‏ ‏مِنْ مَزَامِيرِ آلِ ‏ ‏دَاوُدَ ‏","","",""],[24179,24179,"","আমি আমার ঘোড়াগুলোকে একটা মেয়েকে বাস করার জন্য বলেছিলাম । ঋণ নেওয়ার পর, তিনি তার সঙ্গে দেখা করতে যান এবং তার সঙ্গে দেখা করতে যান ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏سَأَلَهَا رَجُلٌ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ صَوْتَهُ مِنْ اللَّيْلِ إِذَا قَرَأَ قَالَتْ نَعَمْ رُبَّمَا رَفَعَ وَرُبَّمَا خَفَضَ قَالَ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الدِّينِ سَعَةً قَالَ فَهَلْ كَانَ يُوتِرُ مِنْ أَوَّلِ اللَّيْلِ قَالَتْ نَعَمْ رُبَّمَا أَوْتَرَ مِنْ أَوَّلِ اللَّيْلِ وَرُبَّمَا أَوْتَرَ مِنْ آخِرِهِ قَالَ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الدِّينِ سَعَةً ‏","","",""],[24180,24180,"","আমরা যে সব দলের কথা বলেছি তারা কি কখনো ঈশ্বরের কাছে যাবে, সে রাতে থেকে প্রার্থনা করবে। আমি দশ ফুট বিরতি নিয়ে এসেছি, তারপর সে বিস্ফোরিত হবে। এমনকি সে যখন বিস্ফোরণটা হতে শুরু করল, তখনও। প্রার্থনা করার অধিকার রয়েছে","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً فَإِذَا فَجَرَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ ‏ ‏اتَّكَأَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ يُؤْذِنُهُ لِلصَّلَاةِ ‏","","",""],[24181,24181,"","আমরা আমার জীবনের সবচেয়ে ভাল অভিজ্ঞতার কথা বলেছি, তুমি বলেছিলে ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আনন্দ থেকে বেঁচে যাবেন। আর এটা একটা দারুন মহাবী। আমরা কথা বলেছি, আমরা তার কথা বলেছি। তিনি তার সংবাদ শুনে সেই কাজ করেছিলেন এবং তার জীবনে গিয়েছিলেন । ঈশ্বর হলেন মহান এবং সম্মানিত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ هِشَامٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ بِتِسْعِ رَكَعَاتٍ وَرَكْعَتَيْنِ وَهُوَ جَالِسٌ فَلَمَّا ضَعُفَ أَوْتَرَ بِسَبْعٍ وَرَكْعَتَيْنِ وَهُوَ جَالِسٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ هِشَامِ بْنِ عَامِرٍ ‏ ‏وَكَانَ جَارًا لَهُ أَخْبَرَهُ فَذَكَرَ الْحَدِيثَ وَأَنَّهُ دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَتْ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي تِسْعَ رَكَعَاتٍ لَا يَقْعُدُ فِيهِنَّ إِلَّا عِنْدَ الثَّامِنَةِ فَيَحْمَدُ اللَّهَ عَزَّ وَجَلَّ وَيَذْكُرُهُ وَيَدْعُو ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ ثُمَّ ‏ ‏يُصَلِّي التَّاسِعَةَ فَيَقْعُدُ يَحْمَدُ اللَّهَ عَزَّ وَجَلَّ وَيَذْكُرُهُ وَيَدْعُو ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا ثُمَّ ‏ ‏يُصَلِّي رَكْعَتَيْنِ وَهُوَ قَاعِدٌ ‏","","",""],[24182,24182,"","আমরা যৌন মিলনের ব্যাপারে কথা বলেছি। ঈশ্বর... ...সুস্থের প্রার্থনা করবেন... ...আমাদের কাছে ঈশ্বরের মূল্যবান কিছু আছে। আমার সাথে শত্রু বলেন","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ الضُّحَى أَرْبَعَ رَكَعَاتٍ وَيَزِيدُ مَا شَاءَ اللَّهُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏مُعَاذَةُ الْعَدَوِيَّةُ ‏ ‏فَذَكَرَهُ ‏","","",""],[24183,24183,"","আমরা যে - সময়ে মজা করছিলাম, সেই সম্বন্ধে আমরা সবচেয়ে ভাল কথা বলেছিলাম । আর সে-ই বা যে তাকে আদেশ করেছে তাকে নয় যে এটা করতে চায়। এটা হারানোর এবং ভয় পেয়ে যেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا سَبَّحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَةَ الضُّحَى قَالَ وَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتْرُكُ الْعَمَلَ وَإِنَّهُ لَيُحِبُّ أَنْ يَعْمَلَهُ مَخَافَةَ أَنْ ‏ ‏يَسْتَنَّ ‏ ‏بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ قَالَتْ وَكَانَ يُحِبُّ مَا خَفَّ عَلَى النَّاسِ ‏","","",""],[24184,24184,"","আমরা পৃথিবীর বিয়ের সময়ের সবচেয়ে ভালো সময় নিয়ে কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং প্রভুর কাছে প্রার্থনা করেছেন, আর প্রভুর কাছে প্রার্থনা করেছেন তার প্রভুর কাছে আমি প্রভুর কাছে আত্মসমর্পণ করলাম, সে হাঁটু গেড়ে বসলো, আর সে বলটা নিয়ে বড় হয়ে গেল, আর সে পরে বলটা হাতে তুলে দিল আর সে পরে পরে সেটা পড়ার জন্য তার মাথা তুলে ধরেছিল, সে দুটো খুঁজে পেয়েছে। আর তারপর সে তোমার মতো দ্বিতীয় স্থানে যায়, যদি তার জীবনের একমাত্র মৃত্যু হয়, কিন্তু তারা ঈশ্বরের মুখ থেকে জিতে যেত, যদি না সে তোমাকে দেখেও জিতে যেত। তার বাবার এই জীবনের জন্য মানসিকভাবে দুঃখিত... ...সে এই রকমই জিতেছে... ...তাই সে তোমাকে দেখেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى بِالنَّاسِ فَأَطَالَ الْقِرَاءَةَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ رَأْسَهُ فَأَطَالَ الْقِرَاءَةَ وَهِيَ دُونَ قِرَاءَتِهِ الْأُولَى ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ وَهُوَ دُونَ رُكُوعِهِ الْأَوَّلِ ثُمَّ رَفَعَ رَأْسَهُ فَسَجَدَ سَجْدَتَيْنِ ثُمَّ قَامَ فَصَنَعَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ ثُمَّ انْصَرَفَ فَقَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ وَلَكِنَّهُمَا آيَتَانِ مِنْ آيَاتِ اللَّهِ عَزَّ وَجَلَّ فَإِذَا رَأَيْتُمْ ذَلِكَ فَافْزَعُوا لِلصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَ هَذَا وَزَادَ قَالَ فَإِذَا رَأَيْتُمْ ذَلِكَ فَتَصَدَّقُوا وَصَلُّوا ‏","","",""],[24185,24185,"","আমরা সবার মধ্যে থেকে ভালো কথা বলেছি... ...যে আমরা বেঁচে আছি সে কথা দিয়েছি... ...আর ঈশ্বর তার কথা দিয়েছেন যে তারা সবাই ভালো আছে আর তারা কাপুরুষ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْهَا ‏ ‏أَنَّهُمَا ‏ ‏شَرَعَا ‏ ‏جَمِيعًا وَهُمَا جُنُبٌ فِي إِنَاءٍ وَاحِدٍ ‏","","",""],[24186,24186,"","বিয়ের ব্যাপারে আমরা যে - বিয়ের কথা বলেছিলাম, সেই বিষয়ে আমরা কথা বলেছিলাম । এস্নোনিয়ার অনুপ্রেরণার অনুপ্রেরণার ধারার প্রান্তরে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُلِقَتْ الْمَلَائِكَةُ مِنْ نُورٍ وَخُلِقَ الْجَانُّ مِنْ ‏ ‏مَارِجٍ ‏ ‏مِنْ نَارٍ وَخُلِقَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مِمَّا وُصِفَ لَكُمْ ‏","","",""],[24187,24187,"","আমরা পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি, আর আমি একটি ছেলে আছে যে তোমাকে শুনানির কথা বলেছে, আর তোমার কথা বলেছে, আমি ভয় পাচ্ছি এটা তার জন্য করা সবচেয়ে ভাল কাজ। লর্ড তার জন্য প্রার্থনা করেছে এবং তার জন্য প্রার্থনা করেছে। ( খ) কেন আমাদের ঈশ্বরের প্রতি অনুগত থাকা উচিত?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ الْمُعْتَكِفِ وَكَيْفَ سُنَّتُهُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَعُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَخْبَرَتْهُمَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْتَكِفُ ‏ ‏فِي الْعَشْرِ الْأَوَاخِرِ مِنْ شَهْرِ رَمَضَانَ حَتَّى تَوَفَّاهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[24188,24188,"","আমি প্রার্থনা করি ঈশ্বর তার শোক ভেঙ্গে দেবেন এবং বলেন যে তিনি জীবিত আছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ سَعِيدٍ أَخِي يَحْيَي بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَسْرُ عَظْمِ الْمَيِّتِ كَكَسْرِهِ وَهُوَ حَيٌّ ‏ ‏قَالَ ‏ ‏يَرَوْنَ أَنَّهُ فِي الْإِثْمِ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَظُنُّهُ قَوْلَ ‏ ‏دَاوُدَ ‏","","",""],[24189,24189,"","আমরা পৃথিবীর সেরাদের ব্যাপারে কথা বলেছি, ঈশ্বর হলেন সর্বোত্তম প্রভু ঈশ্বরের সর্বোচ্চ প্রাণে জীবিত। আমি নিশ্চিত হবো আমার বাবা যেন তার সাথে যোগাযোগ করে। ( যিশাইয় ১১: ৬) ঈশ্বর কেবল এই প্রার্থনা করেছেন । এটা রেখে দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ بْنِ حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَرْسَلَتْ هِيَ وَأَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى أَهْلِ ‏ ‏سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنْ مُرُّوا بِهِ عَلَيْنَا فِي الْمَسْجِدِ فَصَلَّى عَلَيْهِ أَزْوَاجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْكَرَ ذَلِكَ النَّاسُ فَذُكِرَ ذَلِكَ ‏ ‏لِعَائِشَةَ ‏ ‏فَقَالَتْ أَلَا تَعْجَبُونَ مِنْ النَّاسِ حِينَ يُنْكِرُونَ هَذَا فَوَاللَّهِ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏سَهْلِ بْنِ بَيْضَاءَ ‏ ‏إِلَّا فِي الْمَسْجِدِ ‏","","",""],[24190,24190,"","আমরা একটা বড় কান্নার কথা বলেছিলাম, যেটা আমরা বলেছিলাম ফুলগুলো আমি বলেছিলাম কারণ আমার বাবার সঙ্গে সুখের জীবন নিয়ে কথা বলা আমার প্রভুর জন্য উপযুক্ত । আমার বাবার দয়া শুনে আমি তার কাছে যে - ঘটনা শুনেছিলাম, সেটা শুনে আমি অবাক হয়ে গিয়েছিলাম । তার","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ حَدِيثِ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏وَابْنِ الْمُسَيَّبِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَسَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ ثُمَّ لَمْ يَزَلْ يَفْعَلُ ذَلِكَ حَتَّى تَوَفَّاهُ الْمَوْتُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْت ‏ ‏أَبِي ‏ ‏يَقُولُ هَذَا الْحَدِيثُ هُوَ هَكَذَا فِي كِتَابِ الصِّيَامِ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَائِشَةَ ‏ ‏وَفِي ‏ ‏الِاعْتِكَافِ عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَحْدَهَا ‏","","",""],[24191,24191,"","আমরা সেরাদের ব্যাপারে কথা বলেছি, আমি বলেছি লর্ড শক্তিশালী হও, আমি তাকে বলে দিয়েছি যে, আমি তার সংবাদ সরাসরি সরাসরি জানাচ্ছি, নবী তাকে ছেড়ে দিবেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏يَزْعُمُ أَنَّ ‏ ‏عُرْوَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَدْخُلْ عَلَيْهَا قَطُّ بَعْدَ الْعَصْرِ إِلَّا رَكَعَ رَكْعَتَيْنِ ‏","","",""],[24192,24192,"","আমার বাবা ও আমি বলেছিলাম যে, ঈশ্বর আপনার কথা শোনেন । ঈশ্বরের ইচ্ছা ছিল যেন তিনি বেঁচে থাকেন। আর তিনি প্রভুর কাছে প্রার্থনা করেন, যেন তিনি তার প্রভুর কাছে নিজেকে সমর্পণ করেন,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُبَيْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي مُلَيْكَةَ ‏ ‏سَمِعْتُ ‏ ‏أَهْلَ ‏ ‏عَائِشَةَ ‏ ‏يَذْكُرُونَ عَنْهَا أَنَّهَا كَانَتْ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَدِيدَ ‏ ‏الْإِنْصَابِ ‏ ‏لِجَسَدِهِ فِي الْعِبَادَةِ غَيْرَ أَنَّهُ حِينَ دَخَلَ فِي السِّنِّ وَثَقُلَ مِنْ اللَّحْمِ كَانَ أَكْثَرُ مَا ‏ ‏يُصَلِّي وَهُوَ قَاعِدٌ ‏","","",""],[24193,24193,"","আমরা একটা কুকুর ছেলের কথা বলেছিলাম যে আমার বাবা কখনোই আমাকে বলেননি যে আমি তাকে জীবিত বলতে চাই তাকে বলতে যে ভাববাদী তার জন্য প্রার্থনা করেছেন আর তার শান্তি নেই তার প্রার্থনা গ্রেস.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُثْمَانُ بْنُ أَبِي سُلَيْمَانَ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَمُتْ حَتَّى صَارَ ‏ ‏يُصَلِّي كَثِيرًا مِنْ صَلَاتِهِ وَهُوَ جَالِسٌ ‏","","",""],[24194,24194,"","আমরা একটা ভয়ঙ্কর ছেলের কথা বলেছিলাম, সে রাতে রাতে রাতে রাতে রাতে ঈশ্বরের কাছে প্রার্থনা করতো। আমি যাচ্ছি। মানুষ এটা ভালো হওয়ার কথা বলে আর এর সাথে চলে যাওয়া নিয়ে কথা বলে। তোমার সাথে তৃতীয় রাতে দেখা হয়ে... ...সে রাতে তার সাথে প্রার্থনা করেছিল যখন সে ছিল মানুষের রাতের শুভ রাত্রি. আর তারা তাকে কখনোই যেতে দিবে না যতক্ষণ না আমি শুনলাম যে মানুষ হারিয়ে গেছে। সে ইতমধ্যে নাচে উপত্যকা ছেড়ে দেবে, তারপর সে মানুষের কাছে আসবে, তারপর সে বলবে ও বলবে ও অবশ্যই মরবে বিজয়ী, কিন্তু আমি ভয় পেয়েছিলাম আপনি এটা করতে খুশি হবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏قَالَ قَالَ ‏ ‏عُرْوَةُ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً مِنْ جَوْفِ اللَّيْلِ فَصَلَّى فِي الْمَسْجِدِ ‏ ‏فَثَابَ ‏ ‏رِجَالٌ فَصَلَّوْا مَعَهُ بِصَلَاتِهِ فَلَمَّا أَصْبَحَ النَّاسُ تَحَدَّثُوا أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ خَرَجَ فَصَلَّى فِي الْمَسْجِدِ مِنْ جَوْفِ اللَّيْلِ فَاجْتَمَعَ اللَّيْلَةَ الْمُقْبِلَةَ أَكْثَرُ مِنْهُمْ قَالَتْ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْتَسَلَ مِنْ جَوْفِ اللَّيْلِ فَصَلَّى وَصَلَّوْا مَعَهُ بِصَلَاتِهِ ثُمَّ أَصْبَحَ فَتَحَدَّثُوا بِذَلِكَ فَاجْتَمَعَ اللَّيْلَةَ الثَّالِثَةَ نَاسٌ كَثِيرٌ حَتَّى كَثُرَ أَهْلُ الْمَسْجِدِ قَالَتْ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ جَوْفِ اللَّيْلِ فَصَلَّى فَصَلَّوْا مَعَهُ فَلَمَّا كَانَتْ اللَّيْلَةُ الرَّابِعَةُ اجْتَمَعَ النَّاسُ حَتَّى كَادَ الْمَسْجِدُ يَعْجَزُ عَنْ أَهْلِهِ فَجَلَسَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَخْرُجْ قَالَتْ حَتَّى سَمِعْتُ نَاسًا مِنْهُمْ يَقُولُونَ الصَّلَاةَ فَلَمْ يَخْرُجْ إِلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا صَلَّى صَلَاةَ الْفَجْرِ سَلَّمَ ثُمَّ قَامَ فِي النَّاسِ فَتَشَهَّدَ ثُمَّ قَالَ أَمَّا بَعْدُ فَإِنَّهُ لَمْ يَخْفَ عَلَيَّ شَأْنُكُمْ اللَّيْلَةَ وَلَكِنِّي خَشِيتُ أَنْ تُفْرَضَ عَلَيْكُمْ فَتَعْجَزُوا عَنْهَا ‏","","",""],[24195,24195,"","আমরা সবার সেরা লোকদের কথা বলেছি যারা আমাদের বলেছে যে একটা কুকুর একটা বাচ্চা একটা মেয়েকে খুঁজতে এসেছে যে একটা মেয়ে ছিল যে ছিল মহিলা। যে মহিলা ছিলেন নারী নারী, সে ছিল নারী নারী, যে ছিল নারী মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা, যে ছিল মহিলা মহিলা মহিলা মহিলা মহিলা মহিলা, যে ছিল মহিলা মহিলা মহিলা, যে ছিল মহিলা মহিলা। তিনি ঈশ্বরের কাছে প্রার্থনা করছিলেন যেন তিনি তার আদেশ প্রদান করেন এবং কামনাকারীকে এই কামনা করেন। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏كَانَتْ تَقُولُ ‏ ‏مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي سُبْحَةَ الضُّحَى قَالَ وَكَانَتْ ‏ ‏عَائِشَةُ ‏ ‏تُسَبِّحُهَا وَكَانَتْ تَقُولُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَتْرُكُ الْعَمَلَ خَشْيَةَ أَنْ ‏ ‏يَسْتَنَّ ‏ ‏بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ ‏","","",""],[24196,24196,"","আমি বলেছিলাম যে ভাববাদী তার জন্য প্রার্থনা করছেন আর শিয়ালি থেকে কিছু শিখতে পারবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّهُ أَخْبَرَ عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى شَيْءٍ مِنْ النَّوَافِلِ بِأَشَدَّ مُعَاهَدَةً مِنْهُ عَلَى الرَّكْعَتَيْنِ أَمَامَ الصُّبْحِ ‏ ‏سَمِعْتُ هَذَا مِنْ ‏ ‏عَطَاءٍ ‏ ‏مِرَارًا ‏","","",""],[24197,24197,"","আমরা একটি দশ বছরের ধনী পরিবারের সাথে দেখা করতে পেরে খুশির সাথে কথা বলেছি। লর্ড প্রার্থনা করলেন এবং কোরানের এই দক্ষতায় তিনি আত্মসমর্পন করবেন। সম্মানিত এবং সে যে লক্ষণ দেখে, সে হবে সেই ভল্লুত, যে তার দুই ভাড়া উপভোগ করে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْمَاهِرُ ‏ ‏فِي الْقُرْآنِ مَعَ ‏ ‏السَّفَرَةِ ‏ ‏الْكِرَامِ الْبَرَرَةِ وَالَّذِي يَقْرَأُ وَهُوَ عَلَيْهِ شَاقٌّ يَتَتَعْتَعُ فِيهِ لَهُ أَجْرَانِ اثْنَانِ ‏","","",""],[24198,24198,"","আমরা পৃথিবীর সবচেয়ে খারাপ দৃষ্টি সম্পর্কে কথা বলেছি। তার আনুগত্য তাকে আদেশ করেছে এবং আত্মসমর্পণ করেছে যখন অনুগতরা তাকে দিতে না পারলে আমি তাকে ঘৃণা করি। তিনি তাকে তার বিবাহ থেকে বের করে আনতে হবে, শ্বাস নিতে হবে এবং একবার চলে যাওয়ার পর মুক্তি পাবে। কখনোই স্বাধীন হতে হয়নি।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏اشْتَرَيْتُ ‏ ‏بَرِيرَةَ ‏ ‏فَاشْتَرَطَ أَهْلُهَا ‏ ‏وَلَاءَهَا ‏ ‏فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِيهَا فَأَعْتِقِيهَا فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْطَى ‏ ‏الْوَرِقَ ‏ ‏قَالَتْ فَاشْتَرَيْتُهَا فَأَعْتَقْتُهَا قَالَتْ فَدَعَاهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَيَّرَهَا مِنْ زَوْجِهَا فَاخْتَارَتْ نَفْسَهَا وَكَانَ زَوْجُهَا حُرًّا ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏مِثْلَ حَدِيثِ ‏ ‏مَنْصُورٍ ‏ ‏إِلَّا أَنَّهُ قَالَ كَانَ زَوْجُهَا عَبْدًا وَلَوْ كَانَ حُرًّا لَمْ يُخَيِّرْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24199,24199,"","আমরা প্রভুর প্রভুর প্রভুর প্রভুর প্রভুর প্রার্থনা নিয়ে কথা বলেছি, তিনি বলেছিলেন, তাঁকে ঈশ্বর এবং ঈশ্বরের কাছে উদ্ধার করা হয়েছে। এই সূক্ষ্ম বুদ্ধিটি তাকে পাগলামীর মধ্য থেকে জিজ্ঞাসা করা হবে যখন তিনি একজন উন্মাদ হয়ে যান বিজয়ী।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏سَيَّارٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي ‏ ‏الْمِخْضَبَ ‏ ‏فَيَغْتَسِلُ مِنْهُ مِنْ الْجَنَابَةِ بَعْدَمَا يُصْبِحُ ثُمَّ يَظَلُّ يَوْمَهُ ذَلِكَ صَائِمًا ‏","","",""],[24200,24200,"","আমরা রাজার শক্তিশালীদের কথা বলেছি তাকে একটা জীবন্ত জীবন দিতে যে আমাকে হত্যা করা হয়েছে তাকে একটা ব্লক থেকে উদ্ধার করা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""]];
